(function() {
    "use strict";

    // 1. KODE TEMPLAT LENGKAP GAME 3D NEON VELOCITY (STARTER CODE)
    const STARTER_CODE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n    <title>Neon Velocity - Cyberpunk 3D Hypercar Driving Simulator</title>\n    \n    <!-- Tailwind CSS CDN -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    \n    <!-- Google Fonts: Orbitron & Inter -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800&family=Orbitron:wght@400;600;800;900&display=swap\" rel=\"stylesheet\">\n    \n    <!-- Font Awesome Icons -->\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n\n    <!-- Three.js Core & Post-Processing (Urutan Dependensi Benar) -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/shaders/CopyShader.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/shaders/LuminosityHighPassShader.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/postprocessing/ShaderPass.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/postprocessing/EffectComposer.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/postprocessing/RenderPass.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/postprocessing/UnrealBloomPass.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/shaders/FilmShader.js\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/postprocessing/FilmPass.js\"></script>\n\n    <style>\n        * {\n            box-sizing: border-box;\n            user-select: none;\n            -webkit-user-select: none;\n            touch-action: manipulation;\n        }\n\n        body, html {\n            margin: 0;\n            padding: 0;\n            width: 100%;\n            height: 100%;\n            overflow: hidden;\n            background-color: #030108;\n            font-family: 'Inter', sans-serif;\n            color: #ffffff;\n        }\n\n        .font-orbitron {\n            font-family: 'Orbitron', sans-serif;\n        }\n\n        /* Y2K Slanted Frames Aesthetic */\n        .y2k-panel {\n            background: rgba(10, 6, 22, 0.88);\n            backdrop-filter: blur(14px);\n            border-left: 4px solid #00ff88;\n            border-right: 2px solid #00f3ff;\n            box-shadow: 0 0 20px rgba(0, 255, 136, 0.3), inset 0 0 15px rgba(0, 243, 255, 0.2);\n            transform: skewX(-10deg);\n        }\n\n        .y2k-unskew {\n            transform: skewX(10deg);\n        }\n\n        .retro-pixelated {\n            image-rendering: pixelated;\n            image-rendering: crisp-edges;\n        }\n\n        /* Radial Motion Blur Overlay during Nitro Boost */\n        .radial-blur-overlay {\n            pointer-events: none;\n            position: absolute;\n            top: 0; left: 0; width: 100%; height: 100%;\n            z-index: 38;\n            opacity: 0;\n            transition: opacity 0.25s ease-in-out;\n            background: radial-gradient(circle at center, transparent 20%, rgba(0, 243, 255, 0.35) 75%, rgba(255, 0, 128, 0.6) 100%);\n            mix-blend-mode: screen;\n        }\n\n        /* Glassmorphism panel style */\n        .glass-panel {\n            background: rgba(12, 8, 28, 0.82);\n            backdrop-filter: blur(16px);\n            -webkit-backdrop-filter: blur(16px);\n            border: 1px solid rgba(255, 255, 255, 0.15);\n            box-shadow: 0 12px 40px 0 rgba(0, 0, 0, 0.7);\n        }\n\n        .glass-panel-interactive {\n            background: rgba(22, 12, 48, 0.88);\n            backdrop-filter: blur(16px);\n            border: 1px solid rgba(255, 120, 30, 0.45);\n            transition: all 0.2s ease-in-out;\n            cursor: pointer;\n        }\n\n        .glass-panel-interactive:hover {\n            border-color: rgba(0, 243, 255, 0.8);\n            box-shadow: 0 0 25px rgba(0, 243, 255, 0.45);\n            transform: translateY(-1px);\n        }\n\n        /* Vignette & Speed Flare Layer */\n        .vignette-overlay {\n            pointer-events: none;\n            position: absolute;\n            top: 0; left: 0; width: 100%; height: 100%;\n            z-index: 35;\n            box-shadow: inset 0 0 140px rgba(3, 1, 10, 0.9), inset 0 0 60px rgba(255, 80, 20, 0.3);\n        }\n\n        .speed-vignette {\n            pointer-events: none;\n            position: absolute;\n            top: 0; left: 0; width: 100%; height: 100%;\n            z-index: 36;\n            opacity: 0;\n            transition: opacity 0.3s ease;\n            background: radial-gradient(circle, transparent 50%, rgba(0, 243, 255, 0.3) 100%);\n        }\n\n        .palette-chip.active {\n            border-color: #ff6600 !important;\n            transform: scale(1.04);\n            box-shadow: 0 0 15px rgba(255, 102, 0, 0.6);\n        }\n\n        @keyframes hyperGlow {\n            0%, 100% { text-shadow: 0 0 14px rgba(255, 102, 0, 0.9), 0 0 30px rgba(255, 60, 0, 0.6); }\n            50% { text-shadow: 0 0 25px rgba(0, 243, 255, 1.0), 0 0 45px rgba(0, 243, 255, 0.8); }\n        }\n\n        .hyper-text-glow {\n            animation: hyperGlow 3s infinite alternate;\n        }\n\n        canvas {\n            display: block;\n            width: 100%;\n            height: 100%;\n        }\n    </style>\n</head>\n<body class=\"bg-black text-white overflow-hidden select-none\">\n\n    <!-- WebGL Canvas Container -->\n    <div id=\"canvas-container\" class=\"absolute inset-0 z-0\"></div>\n\n    <!-- Post-Processing Visual Overlays -->\n    <div id=\"vignette-layer\" class=\"vignette-overlay\"></div>\n    <div id=\"speed-layer\" class=\"speed-vignette\"></div>\n    <div id=\"nitro-blur-layer\" class=\"radial-blur-overlay\"></div>\n\n    <!-- MAIN HUD DISPLAY -->\n    <div id=\"hud-layer\" class=\"absolute inset-0 z-10 pointer-events-none flex flex-col justify-between p-4 md:p-6\">\n        \n        <!-- Top HUD Row: Speedometer, Score, Camera View & Shield -->\n        <div class=\"flex items-start justify-between w-full max-w-7xl mx-auto\">\n            \n            <!-- 2000s Y2K Style Speedometer Display -->\n            <div class=\"y2k-panel p-3 md:p-4 rounded-xl flex items-center gap-4 border-l-4 border-lime-400\">\n                <div class=\"y2k-unskew flex items-center gap-3\">\n                    <div class=\"relative w-16 h-16 md:w-20 md:h-20 flex items-center justify-center\">\n                        <canvas id=\"speedo-gauge\" width=\"100\" height=\"100\" class=\"absolute inset-0\"></canvas>\n                        <div class=\"text-center z-10\">\n                            <span id=\"hud-speed\" class=\"font-orbitron text-2xl md:text-3xl font-black text-lime-400 block leading-none italic\">0</span>\n                            <span class=\"text-[9px] md:text-[10px] text-lime-200 tracking-widest uppercase font-bold\">KM/H</span>\n                        </div>\n                    </div>\n                    <div class=\"hidden sm:block\">\n                        <div class=\"text-[10px] text-lime-300 font-bold uppercase tracking-wider\">RPM / GEAR</div>\n                        <div id=\"hud-gear\" class=\"font-orbitron text-lg font-black text-cyan-400 italic\">4th MAX</div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Center Score & Distance -->\n            <div class=\"flex flex-col items-center\">\n                <div class=\"y2k-panel px-6 py-2.5 rounded-xl border border-lime-400/60 text-center mb-2\">\n                    <div class=\"y2k-unskew\">\n                        <span class=\"text-[10px] text-lime-400 font-bold uppercase tracking-widest block\">DISTANCE</span>\n                        <span id=\"hud-distance\" class=\"font-orbitron text-2xl md:text-3xl font-black text-white italic tracking-wider\">0000 <span class=\"text-xs text-lime-400 font-normal\">M</span></span>\n                    </div>\n                </div>\n                \n                <!-- Combo Multiplier Badge -->\n                <div id=\"hud-combo-container\">\n                    <span class=\"y2k-panel px-3.5 py-1 rounded-lg text-xs font-orbitron font-bold text-yellow-300 border border-yellow-400 flex items-center gap-1.5 shadow-lg\">\n                        <span class=\"y2k-unskew flex items-center gap-1.5\">\n                            <i class=\"fa-solid fa-bolt text-yellow-400 animate-pulse\"></i>\n                            NITRO MULT <span id=\"hud-multiplier\" class=\"text-sm font-black\">1.0x</span>\n                        </span>\n                    </span>\n                </div>\n            </div>\n\n            <!-- Right HUD: Shield & Stats -->\n            <div class=\"glass-panel p-3 md:p-4 rounded-2xl flex flex-col gap-2 border-r-4 border-cyan-400 min-w-[140px] md:min-w-[180px]\">\n                <div class=\"flex items-center justify-between text-xs text-gray-300\">\n                    <span class=\"flex items-center gap-1.5 font-semibold\">\n                        <i id=\"shield-icon\" class=\"fa-solid fa-shield-halved text-cyan-400 text-sm\"></i> SHIELD\n                    </span>\n                    <span id=\"hud-shield-status\" class=\"font-orbitron text-cyan-300 font-bold\">READY</span>\n                </div>\n                <!-- Shield Meter Bar -->\n                <div class=\"w-full h-2.5 bg-gray-950 rounded-full overflow-hidden border border-cyan-500/40 p-0.5\">\n                    <div id=\"hud-shield-bar\" class=\"h-full bg-gradient-to-r from-cyan-500 to-blue-500 rounded-full w-full transition-all duration-300 shadow-sm shadow-cyan-400\"></div>\n                </div>\n\n                <div class=\"flex items-center justify-between text-xs text-gray-300 mt-1\">\n                    <span class=\"flex items-center gap-1.5 font-semibold\">\n                        <i class=\"fa-solid fa-car-burst text-orange-400\"></i> DODGED\n                    </span>\n                    <span id=\"hud-dodged\" class=\"font-orbitron text-orange-400 font-bold\">0</span>\n                </div>\n            </div>\n        </div>\n\n        <!-- Bottom HUD Row: Nitro Bar & Mobile Controls -->\n        <div class=\"w-full max-w-4xl mx-auto flex flex-col items-center gap-3\">\n            \n            <!-- Nitro Boost Gauge -->\n            <div class=\"w-full glass-panel px-4 py-3 rounded-2xl flex items-center gap-3 border border-orange-500/50 shadow-xl shadow-orange-950/40\">\n                <span class=\"font-orbitron text-xs text-amber-400 font-bold flex items-center gap-1.5 min-w-[80px]\">\n                    <i class=\"fa-solid fa-fire-flame-curved text-amber-400 text-sm animate-pulse\"></i> NITRO\n                </span>\n                <div class=\"flex-1 h-4 bg-gray-950 rounded-full p-0.5 border border-amber-500/50 relative overflow-hidden\">\n                    <div id=\"hud-nitro-bar\" class=\"h-full bg-gradient-to-r from-amber-500 via-orange-500 to-red-500 rounded-full w-full transition-all duration-100 shadow-md shadow-orange-500/60\"></div>\n                </div>\n                <span id=\"hud-nitro-percent\" class=\"font-orbitron text-xs font-black text-amber-300 w-12 text-right\">100%</span>\n            </div>\n\n            <!-- Mobile Touch Overlay Controls -->\n            <div id=\"mobile-controls\" class=\"pointer-events-auto flex items-center justify-between w-full max-w-md px-2 py-1 md:hidden\">\n                <button id=\"btn-steer-left\" class=\"w-16 h-16 rounded-2xl glass-panel-interactive flex items-center justify-center text-cyan-400 text-2xl active:scale-95 shadow-lg\">\n                    <i class=\"fa-solid fa-chevron-left\"></i>\n                </button>\n                <button id=\"btn-nitro-boost\" class=\"px-6 h-14 rounded-2xl bg-gradient-to-r from-orange-500 via-amber-500 to-yellow-400 font-orbitron font-black text-black text-sm tracking-widest active:scale-95 shadow-lg shadow-orange-500/40 flex items-center gap-2\">\n                    <i class=\"fa-solid fa-bolt\"></i> BOOST\n                </button>\n                <button id=\"btn-steer-right\" class=\"w-16 h-16 rounded-2xl glass-panel-interactive flex items-center justify-center text-cyan-400 text-2xl active:scale-95 shadow-lg\">\n                    <i class=\"fa-solid fa-chevron-right\"></i>\n                </button>\n            </div>\n        </div>\n    </div>\n\n    <!-- Top Right Action Controls -->\n    <div class=\"absolute top-4 right-4 z-20 flex items-center gap-2\">\n        <button id=\"btn-cam-switch\" class=\"px-3 h-10 rounded-xl glass-panel-interactive flex items-center gap-2 text-xs font-orbitron text-amber-400 hover:text-white transition-colors\" title=\"Change Camera View\">\n            <i class=\"fa-solid fa-camera\"></i> <span id=\"cam-label\" class=\"hidden sm:inline\">CHASE</span>\n        </button>\n        <button id=\"btn-audio-toggle\" class=\"w-10 h-10 rounded-xl glass-panel-interactive flex items-center justify-center text-orange-400 hover:text-cyan-300 transition-colors\" title=\"Toggle Audio\">\n            <i class=\"fa-solid fa-volume-high text-sm\"></i>\n        </button>\n        <button id=\"btn-pause\" class=\"w-10 h-10 rounded-xl glass-panel-interactive flex items-center justify-center text-cyan-400 hover:text-orange-400 transition-colors\" title=\"Pause Game\">\n            <i class=\"fa-solid fa-pause text-sm\"></i>\n        </button>\n    </div>\n\n    <!-- START / MAIN MENU OVERLAY -->\n    <div id=\"menu-overlay\" class=\"absolute inset-0 z-30 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md transition-opacity duration-300\">\n        <div class=\"glass-panel max-w-lg w-full rounded-3xl p-6 md:p-8 border border-orange-500/50 text-center flex flex-col items-center gap-5 shadow-2xl relative overflow-hidden\">\n            \n            <div class=\"absolute -top-24 left-1/2 -translate-x-1/2 w-64 h-64 bg-orange-500/30 rounded-full blur-3xl pointer-events-none\"></div>\n\n            <div>\n                <div class=\"inline-block px-3.5 py-1 rounded-full bg-orange-500/20 border border-orange-500/40 text-orange-400 font-orbitron text-[11px] tracking-widest mb-2 font-bold\">\n                    HYPERCAR SYNTHWAVE SIMULATOR\n                </div>\n                <h1 class=\"font-orbitron text-3xl md:text-5xl font-black tracking-wider text-transparent bg-clip-text bg-gradient-to-r from-amber-300 via-orange-500 to-cyan-400 hyper-text-glow\">\n                    NEON VELOCITY\n                </h1>\n                <p class=\"text-xs md:text-sm text-gray-300 mt-2 max-w-xs mx-auto leading-relaxed\">\n                    Kemudikan hypercar 3D melintasi cyber highway bertabur neon, hindari lalu lintas padat, dan kumpulkan power crystals.\n                </p>\n            </div>\n\n            <div class=\"w-full glass-panel py-3 px-4 rounded-xl flex items-center justify-between border border-amber-500/40\">\n                <span class=\"text-xs text-amber-300 font-semibold tracking-wider flex items-center gap-2\">\n                    <i class=\"fa-solid fa-trophy text-yellow-400\"></i> REKOR JARAK\n                </span>\n                <span id=\"menu-high-score\" class=\"font-orbitron font-black text-yellow-400 text-lg\">00000 M</span>\n            </div>\n\n            <div class=\"w-full text-left\">\n                <label class=\"text-xs text-gray-400 font-semibold uppercase tracking-wider block mb-2\">Tema Palet Visual</label>\n                <div class=\"grid grid-cols-2 gap-2\">\n                    <button data-theme=\"outrun\" class=\"theme-chip palette-chip active glass-panel p-2.5 rounded-xl flex items-center gap-2 text-xs font-semibold text-gray-200 border border-orange-500/60\">\n                        <span class=\"w-4 h-4 rounded-full bg-gradient-to-r from-orange-500 to-yellow-400 shadow-sm shadow-orange-400\"></span> Outrun Sunset\n                    </button>\n                    <button data-theme=\"cyberpunk\" class=\"theme-chip palette-chip glass-panel p-2.5 rounded-xl flex items-center gap-2 text-xs font-semibold text-gray-200 border border-transparent\">\n                        <span class=\"w-4 h-4 rounded-full bg-gradient-to-r from-cyan-400 to-purple-600 shadow-sm shadow-cyan-400\"></span> Cyber Neon\n                    </button>\n                    <button data-theme=\"matrix\" class=\"theme-chip palette-chip glass-panel p-2.5 rounded-xl flex items-center gap-2 text-xs font-semibold text-gray-200 border border-transparent\">\n                        <span class=\"w-4 h-4 rounded-full bg-gradient-to-r from-emerald-400 to-green-900 shadow-sm shadow-emerald-400\"></span> Matrix Grid\n                    </button>\n                    <button data-theme=\"vaporwave\" class=\"theme-chip palette-chip glass-panel p-2.5 rounded-xl flex items-center gap-2 text-xs font-semibold text-gray-200 border border-transparent\">\n                        <span class=\"w-4 h-4 rounded-full bg-gradient-to-r from-blue-300 to-pink-300 shadow-sm shadow-pink-400\"></span> Vaporwave\n                    </button>\n                </div>\n            </div>\n\n            <div class=\"w-full grid grid-cols-3 gap-2 text-left\">\n                <div class=\"glass-panel p-2.5 rounded-xl flex flex-col justify-between text-xs\">\n                    <span class=\"text-gray-300 font-medium text-[11px]\">Highway Curve</span>\n                    <input type=\"checkbox\" id=\"toggle-curve\" checked class=\"accent-orange-500 w-4 h-4 rounded cursor-pointer mt-1\">\n                </div>\n                <div class=\"glass-panel p-2.5 rounded-xl flex flex-col justify-between text-xs\">\n                    <span class=\"text-gray-300 font-medium text-[11px]\">Retro Scanlines</span>\n                    <input type=\"checkbox\" id=\"toggle-crt\" checked class=\"accent-amber-400 w-4 h-4 rounded cursor-pointer mt-1\">\n                </div>\n                <div class=\"glass-panel p-2.5 rounded-xl flex flex-col justify-between text-xs\">\n                    <span class=\"text-gray-300 font-medium text-[11px]\">PS2 480p Mode</span>\n                    <input type=\"checkbox\" id=\"toggle-ps2-res\" class=\"accent-lime-400 w-4 h-4 rounded cursor-pointer mt-1\">\n                </div>\n            </div>\n\n            <button id=\"btn-start-game\" class=\"w-full py-4 rounded-2xl bg-gradient-to-r from-amber-400 via-orange-600 to-red-500 font-orbitron font-black text-white text-lg tracking-widest shadow-2xl shadow-orange-500/40 hover:brightness-110 active:scale-[0.98] transition-all flex items-center justify-center gap-3 cursor-pointer\">\n                <i class=\"fa-solid fa-play\"></i> LAUNCH HYPERCAR\n            </button>\n\n            <div class=\"text-[11px] text-gray-400 flex items-center justify-center gap-4 border-t border-gray-800 pt-3 w-full\">\n                <span><kbd class=\"px-1.5 py-0.5 rounded bg-gray-800 text-amber-300 font-orbitron\">A / D</kbd> atau <kbd class=\"px-1.5 py-0.5 rounded bg-gray-800 text-amber-300 font-orbitron\">← / →</kbd> Steer</span>\n                <span><kbd class=\"px-1.5 py-0.5 rounded bg-gray-800 text-orange-400 font-orbitron\">SPACE</kbd> Nitro Boost</span>\n                <span><kbd class=\"px-1.5 py-0.5 rounded bg-gray-800 text-cyan-300 font-orbitron\">C</kbd> Camera</span>\n            </div>\n        </div>\n    </div>\n\n    <!-- GAME OVER OVERLAY -->\n    <div id=\"gameover-overlay\" class=\"absolute inset-0 z-30 hidden flex items-center justify-center p-4 bg-black/85 backdrop-blur-lg\">\n        <div class=\"glass-panel max-w-md w-full rounded-3xl p-6 md:p-8 border border-red-600/60 text-center flex flex-col items-center gap-5 shadow-2xl relative\">\n            \n            <div class=\"w-16 h-16 rounded-full bg-red-500/20 border border-red-500/50 flex items-center justify-center text-red-500 text-3xl mb-1 shadow-lg shadow-red-500/30\">\n                <i class=\"fa-solid fa-triangle-exclamation\"></i>\n            </div>\n\n            <h2 class=\"font-orbitron text-3xl font-black tracking-wider text-red-500\">\n                VEHICLE DESTROYED\n            </h2>\n            <p class=\"text-xs text-gray-400 -mt-3\">Tabrakan berkecepatan tinggi terdeteksi pada arteri siber.</p>\n\n            <div class=\"w-full grid grid-cols-2 gap-3 my-1 text-left\">\n                <div class=\"glass-panel p-3 rounded-xl\">\n                    <span class=\"text-[10px] text-gray-400 uppercase tracking-wider block\">Total Distance</span>\n                    <span id=\"go-distance\" class=\"font-orbitron font-bold text-lg text-white\">0000 M</span>\n                </div>\n                <div class=\"glass-panel p-3 rounded-xl\">\n                    <span class=\"text-[10px] text-gray-400 uppercase tracking-wider block\">Peak Velocity</span>\n                    <span id=\"go-top-speed\" class=\"font-orbitron font-bold text-lg text-amber-400\">0 KM/H</span>\n                </div>\n                <div class=\"glass-panel p-3 rounded-xl\">\n                    <span class=\"text-[10px] text-gray-400 uppercase tracking-wider block\">Dodged Traffic</span>\n                    <span id=\"go-dodged\" class=\"font-orbitron font-bold text-lg text-orange-400\">0</span>\n                </div>\n                <div class=\"glass-panel p-3 rounded-xl\">\n                    <span class=\"text-[10px] text-gray-400 uppercase tracking-wider block\">Cubes Collected</span>\n                    <span id=\"go-cubes\" class=\"font-orbitron font-bold text-lg text-yellow-400\">0</span>\n                </div>\n            </div>\n\n            <button id=\"btn-restart\" class=\"w-full py-3.5 rounded-2xl bg-gradient-to-r from-amber-400 to-orange-500 font-orbitron font-black text-black text-base tracking-widest hover:brightness-110 active:scale-[0.98] transition-all shadow-lg shadow-amber-500/30 cursor-pointer\">\n                REBUILD & RE-ENGAGE\n            </button>\n        </div>\n    </div>\n\n    <!-- PAUSE OVERLAY -->\n    <div id=\"pause-overlay\" class=\"absolute inset-0 z-30 hidden flex items-center justify-center p-4 bg-black/80 backdrop-blur-md\">\n        <div class=\"glass-panel max-w-sm w-full rounded-3xl p-6 border border-cyan-500/40 text-center flex flex-col items-center gap-5 shadow-2xl\">\n            <h2 class=\"font-orbitron text-2xl font-black tracking-wider text-cyan-300\">\n                DRIVE PAUSED\n            </h2>\n            <div class=\"w-full flex flex-col gap-3\">\n                <button id=\"btn-resume\" class=\"w-full py-3 rounded-xl bg-cyan-500 text-black font-orbitron font-bold text-sm tracking-wider hover:bg-cyan-400 cursor-pointer shadow-lg shadow-cyan-500/20\">\n                    RESUME SPEED\n                </button>\n                <button id=\"btn-pause-restart\" class=\"w-full py-3 rounded-xl glass-panel text-orange-400 font-orbitron font-bold text-sm tracking-wider border border-orange-500/40 hover:bg-orange-500/10 cursor-pointer\">\n                    RESTART DRIVE\n                </button>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        const CONFIG = {\n            roadWidth: 22,\n            roadLength: 420,\n            laneCount: 5,\n            baseSpeed: 0.88,\n            maxSpeed: 2.35,\n            nitroSpeedMultiplier: 1.65,\n            trafficSpawnDist: -280,\n            despawnDist: 30\n        };\n\n        const STATE = {\n            active: false,\n            paused: false,\n            speed: 0,\n            targetSpeed: CONFIG.baseSpeed,\n            kmh: 0,\n            topKmh: 0,\n            distance: 0,\n            dodgedTraffic: 0,\n            cubesCollected: 0,\n            multiplier: 1.0,\n            shieldActive: false,\n            shieldPercent: 100,\n            nitroLevel: 100,\n            nitroActive: false,\n            playerX: 0,\n            targetPlayerX: 0,\n            playerRoll: 0,\n            curveFactor: 0,\n            targetCurveFactor: 0,\n            cameraMode: 0,\n            theme: 'outrun',\n            highScore: parseInt(localStorage.getItem('neon_velocity_highscore') || '0', 10)\n        };\n\n        const THEMES = {\n            outrun: {\n                primary: 0xff6600,\n                secondary: 0xffaa00,\n                grid: 0xff007f,\n                horizon: 0x1c0028,\n                sunTop: '#ff0080',\n                sunBottom: '#ffaa00',\n                fog: 0x0f0118,\n                laneGlow: 0xffbb00,\n                skyTop: '#100028',\n                skyBottom: '#ff3366'\n            },\n            cyberpunk: {\n                primary: 0x00f3ff,\n                secondary: 0xb000ff,\n                grid: 0x00d0ff,\n                horizon: 0x04001a,\n                sunTop: '#00f3ff',\n                sunBottom: '#9d00ff',\n                fog: 0x07011a,\n                laneGlow: 0x00f3ff,\n                skyTop: '#030018',\n                skyBottom: '#9900ee'\n            },\n            matrix: {\n                primary: 0x00ff66,\n                secondary: 0x00aa33,\n                grid: 0x00ff44,\n                horizon: 0x001204,\n                sunTop: '#00ff66',\n                sunBottom: '#003311',\n                fog: 0x000d03,\n                laneGlow: 0x00ff88,\n                skyTop: '#000c03',\n                skyBottom: '#005511'\n            },\n            vaporwave: {\n                primary: 0x70d6ff,\n                secondary: 0xff70a6,\n                grid: 0xff9ebb,\n                horizon: 0x16082c,\n                sunTop: '#70d6ff',\n                sunBottom: '#ff70a6',\n                fog: 0x110424,\n                laneGlow: 0xff70a6,\n                skyTop: '#120428',\n                skyBottom: '#e056fd'\n            }\n        };\n\n        class SoundManager {\n            constructor() {\n                this.ctx = null;\n                this.enabled = true;\n                this.engineOsc = null;\n                this.engineGain = null;\n            }\n\n            init() {\n                if (this.ctx) return;\n                try {\n                    const AudioCtx = window.AudioContext || window.webkitAudioContext;\n                    if (AudioCtx) {\n                        this.ctx = new AudioCtx();\n                        this.setupEngineSound();\n                    }\n                } catch (e) {\n                    console.warn(\"Web Audio API not initialized\", e);\n                }\n            }\n\n            setupEngineSound() {\n                if (!this.ctx) return;\n                try {\n                    this.engineOsc = this.ctx.createOscillator();\n                    const subOsc = this.ctx.createOscillator();\n                    this.engineGain = this.ctx.createGain();\n                    const filter = this.ctx.createBiquadFilter();\n\n                    this.engineOsc.type = 'sawtooth';\n                    subOsc.type = 'square';\n                    filter.type = 'lowpass';\n                    filter.frequency.value = 680;\n\n                    this.engineOsc.frequency.value = 55;\n                    subOsc.frequency.value = 27.5;\n                    this.engineGain.gain.value = 0.05;\n\n                    this.engineOsc.connect(filter);\n                    subOsc.connect(filter);\n                    filter.connect(this.engineGain);\n                    this.engineGain.connect(this.ctx.destination);\n\n                    this.engineOsc.start();\n                    subOsc.start();\n                } catch (e) {}\n            }\n\n            playBlowOffValve() {\n                if (!this.ctx || !this.enabled) return;\n                try {\n                    const now = this.ctx.currentTime;\n                    const bufferSize = this.ctx.sampleRate * 0.25;\n                    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);\n                    const data = buffer.getChannelData(0);\n                    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;\n\n                    const noise = this.ctx.createBufferSource();\n                    noise.buffer = buffer;\n                    const filter = this.ctx.createBiquadFilter();\n                    filter.type = 'bandpass';\n                    filter.frequency.setValueAtTime(3200, now);\n                    filter.frequency.exponentialRampToValueAtTime(800, now + 0.22);\n                    filter.Q.value = 3;\n\n                    const gain = this.ctx.createGain();\n                    gain.gain.setValueAtTime(0.35, now);\n                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.22);\n\n                    noise.connect(filter);\n                    filter.connect(gain);\n                    gain.connect(this.ctx.destination);\n                    noise.start(now);\n                } catch (e) {}\n            }\n\n            updateEngine(speedRatio) {\n                if (!this.ctx || !this.enabled || !this.engineOsc) return;\n                try {\n                    const freq = 52 + speedRatio * 190 + Math.random() * 2;\n                    this.engineOsc.frequency.setTargetAtTime(freq, this.ctx.currentTime, 0.05);\n                } catch (e) {}\n            }\n\n            playPickup() {\n                if (!this.ctx || !this.enabled) return;\n                try {\n                    const now = this.ctx.currentTime;\n                    [523.25, 659.25, 783.99, 1046.50].forEach((freq, idx) => {\n                        const osc = this.ctx.createOscillator();\n                        const gain = this.ctx.createGain();\n                        osc.type = 'triangle';\n                        osc.frequency.value = freq;\n                        gain.gain.setValueAtTime(0.12, now + idx * 0.04);\n                        gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.04 + 0.15);\n                        osc.connect(gain);\n                        gain.connect(this.ctx.destination);\n                        osc.start(now + idx * 0.04);\n                        osc.stop(now + idx * 0.04 + 0.15);\n                    });\n                } catch (e) {}\n            }\n\n            playNitro() {\n                if (!this.ctx || !this.enabled) return;\n                try {\n                    const now = this.ctx.currentTime;\n                    const osc = this.ctx.createOscillator();\n                    const gain = this.ctx.createGain();\n                    osc.type = 'sawtooth';\n                    osc.frequency.setValueAtTime(110, now);\n                    osc.frequency.exponentialRampToValueAtTime(520, now + 0.45);\n                    gain.gain.setValueAtTime(0.25, now);\n                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);\n                    osc.connect(gain);\n                    gain.connect(this.ctx.destination);\n                    osc.start(now);\n                    osc.stop(now + 0.5);\n                } catch (e) {}\n            }\n\n            playCrash() {\n                if (!this.ctx || !this.enabled) return;\n                try {\n                    const now = this.ctx.currentTime;\n                    const bufferSize = this.ctx.sampleRate * 0.4;\n                    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);\n                    const data = buffer.getChannelData(0);\n                    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;\n\n                    const noise = this.ctx.createBufferSource();\n                    noise.buffer = buffer;\n                    const filter = this.ctx.createBiquadFilter();\n                    filter.type = 'lowpass';\n                    filter.frequency.setValueAtTime(800, now);\n                    filter.frequency.exponentialRampToValueAtTime(50, now + 0.4);\n\n                    const gain = this.ctx.createGain();\n                    gain.gain.setValueAtTime(0.4, now);\n                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);\n\n                    noise.connect(filter);\n                    filter.connect(gain);\n                    gain.connect(this.ctx.destination);\n                    noise.start(now);\n                } catch (e) {}\n            }\n        }\n\n        const soundFX = new SoundManager();\n\n        let scene, camera, renderer;\n        let composer = null;\n        let filmPass = null;\n        let particlesArray = [];\n        let playerGroup;\n        let roadMesh, gridHelper, sunMesh, sunGlowMesh, starParticles, speedLinesGroup;\n        let underglowLight, headlightSpotL, headlightSpotR;\n        let exhaustFlames = [];\n        let wheelMeshes = [];\n        let laneLinesArray = [];\n        let trafficArray = [];\n        let collectibleArray = [];\n        let sceneryArray = [];\n        let searchlightsArray = [];\n\n        // Procedural Skyscraper Facade Texture with Glowing Windows\n        function createBuildingTexture() {\n            const canvas = document.createElement('canvas');\n            canvas.width = 128;\n            canvas.height = 256;\n            const ctx = canvas.getContext('2d');\n\n            ctx.fillStyle = '#080514';\n            ctx.fillRect(0, 0, 128, 256);\n\n            const colors = ['#00f3ff', '#ff00aa', '#ffaa00', '#00ff88', '#ffffff'];\n            for (let y = 10; y < 250; y += 8) {\n                for (let x = 6; x < 122; x += 8) {\n                    if (Math.random() < 0.42) {\n                        ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)];\n                        ctx.fillRect(x, y, 4, 5);\n                    }\n                }\n            }\n            const tex = new THREE.CanvasTexture(canvas);\n            tex.wrapS = tex.wrapT = THREE.RepeatWrapping;\n            tex.repeat.set(1, 2);\n            return tex;\n        }\n\n        // Procedural Wet Asphalt Normal Map\n        function createAsphaltNormalMap() {\n            const canvas = document.createElement('canvas');\n            canvas.width = 128;\n            canvas.height = 128;\n            const ctx = canvas.getContext('2d');\n            ctx.fillStyle = '#8080ff';\n            ctx.fillRect(0, 0, 128, 128);\n            for (let i = 0; i < 2000; i++) {\n                const x = Math.random() * 128;\n                const y = Math.random() * 128;\n                const c = 110 + Math.floor(Math.random() * 40);\n                ctx.fillStyle = 'rgb(' + c + ',' + c + ',255)';\n                ctx.fillRect(x, y, 1, 1);\n            }\n            const tex = new THREE.CanvasTexture(canvas);\n            tex.wrapS = tex.wrapT = THREE.RepeatWrapping;\n            tex.repeat.set(4, 80);\n            return tex;\n        }\n\n        function initThree() {\n            const container = document.getElementById('canvas-container');\n\n            scene = new THREE.Scene();\n            const currentTheme = THEMES[STATE.theme];\n            scene.background = new THREE.Color(currentTheme.horizon);\n            scene.fog = new THREE.FogExp2(currentTheme.fog, 0.007);\n\n            camera = new THREE.PerspectiveCamera(65, window.innerWidth / window.innerHeight, 0.1, 1200);\n            updateCameraPosition();\n\n            renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: \"high-performance\" });\n            renderer.setSize(window.innerWidth, window.innerHeight);\n            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n            renderer.shadowMap.enabled = true;\n            renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n            container.appendChild(renderer.domElement);\n\n            const ambientLight = new THREE.AmbientLight(0xffffff, 0.85);\n            scene.add(ambientLight);\n\n            const dirLight = new THREE.DirectionalLight(currentTheme.primary, 1.8);\n            dirLight.position.set(15, 45, -30);\n            dirLight.castShadow = true;\n            dirLight.shadow.mapSize.width = 1024;\n            dirLight.shadow.mapSize.height = 1024;\n            scene.add(dirLight);\n\n            buildSunAndSkyline();\n            buildHighwayRoad();\n            buildPlayerCar();\n            buildEnvironmentProps();\n            buildSpeedLines();\n            buildSearchlights();\n\n            // Post-Processing dengan Fallback Aman\n            try {\n                if (typeof THREE.EffectComposer !== 'undefined' && typeof THREE.UnrealBloomPass !== 'undefined') {\n                    const renderScene = new THREE.RenderPass(scene, camera);\n                    const bloomPass = new THREE.UnrealBloomPass(\n                        new THREE.Vector2(window.innerWidth, window.innerHeight),\n                        1.5, // strength\n                        0.4, // radius\n                        0.22 // threshold\n                    );\n\n                    composer = new THREE.EffectComposer(renderer);\n                    composer.addPass(renderScene);\n                    composer.addPass(bloomPass);\n\n                    if (typeof THREE.FilmPass !== 'undefined') {\n                        filmPass = new THREE.FilmPass(0.25, 0.2, 648, false);\n                        composer.addPass(filmPass);\n                    }\n                }\n            } catch (err) {\n                console.warn(\"Post-processing fallback:\", err);\n                composer = null;\n            }\n\n            window.addEventListener('resize', onWindowResize);\n        }\n\n        function updateCameraPosition() {\n            if (STATE.cameraMode === 0) { \n                camera.position.set(STATE.playerX * 0.45, 4.3, 10.5);\n                camera.lookAt(STATE.playerX * 0.7, 1.3, -12);\n            } else if (STATE.cameraMode === 1) { \n                camera.position.set(STATE.playerX, 1.3, -0.6);\n                camera.lookAt(STATE.playerX, 1.05, -30);\n            } else { \n                camera.position.set(STATE.playerX * 0.3, 17.0, -1.5);\n                camera.lookAt(STATE.playerX * 0.5, 0, -20);\n            }\n        }\n\n        function switchCameraView() {\n            STATE.cameraMode = (STATE.cameraMode + 1) % 3;\n            const labels = [\"CHASE\", \"HOOD\", \"BIRD'S EYE\"];\n            const labelEl = document.getElementById('cam-label');\n            if (labelEl) labelEl.innerText = labels[STATE.cameraMode];\n            updateCameraPosition();\n        }\n\n        function buildSunAndSkyline() {\n            const theme = THEMES[STATE.theme];\n            \n            // Giant Gradient Sun with Neon Slat Stripes\n            const sunCanvas = document.createElement('canvas');\n            sunCanvas.width = 512;\n            sunCanvas.height = 512;\n            const ctx = sunCanvas.getContext('2d');\n\n            const gradient = ctx.createLinearGradient(0, 0, 0, 512);\n            gradient.addColorStop(0, theme.sunTop);\n            gradient.addColorStop(0.65, '#ff4400');\n            gradient.addColorStop(1, theme.sunBottom);\n            ctx.fillStyle = gradient;\n            ctx.beginPath();\n            ctx.arc(256, 256, 240, 0, Math.PI * 2);\n            ctx.fill();\n\n            // Retro horizontal scanline cuts\n            ctx.fillStyle = '#050110';\n            for (let y = 260; y < 490; y += 22) {\n                const stripeHeight = Math.pow((y - 250) / 240, 1.4) * 12 + 3;\n                ctx.fillRect(0, y, 512, stripeHeight);\n            }\n\n            const sunGeo = new THREE.PlaneGeometry(160, 160);\n            const sunTex = new THREE.CanvasTexture(sunCanvas);\n            const sunMat = new THREE.MeshBasicMaterial({\n                map: sunTex,\n                transparent: true,\n                depthWrite: false\n            });\n\n            sunMesh = new THREE.Mesh(sunGeo, sunMat);\n            sunMesh.position.set(0, 32, -420);\n            scene.add(sunMesh);\n\n            // Sun Outer Coronal Halo Glow\n            const haloCanvas = document.createElement('canvas');\n            haloCanvas.width = 256;\n            haloCanvas.height = 256;\n            const hCtx = haloCanvas.getContext('2d');\n            const hGrad = hCtx.createRadialGradient(128, 128, 60, 128, 128, 126);\n            hGrad.addColorStop(0, 'rgba(255, 60, 140, 0.45)');\n            hGrad.addColorStop(0.5, 'rgba(255, 140, 0, 0.2)');\n            hGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');\n            hCtx.fillStyle = hGrad;\n            hCtx.fillRect(0, 0, 256, 256);\n\n            const haloTex = new THREE.CanvasTexture(haloCanvas);\n            const haloMat = new THREE.MeshBasicMaterial({\n                map: haloTex,\n                transparent: true,\n                blending: THREE.AdditiveBlending,\n                depthWrite: false\n            });\n            sunGlowMesh = new THREE.Mesh(new THREE.PlaneGeometry(240, 240), haloMat);\n            sunGlowMesh.position.set(0, 32, -425);\n            scene.add(sunGlowMesh);\n\n            // Cyber City Skyline with Glowing Windows & Hologram Spires\n            const bldgTexture = createBuildingTexture();\n            const skylineGroup = new THREE.Group();\n\n            for (let i = -18; i <= 18; i++) {\n                if (Math.abs(i) < 2) continue;\n                const width = 10 + Math.random() * 12;\n                const height = 25 + Math.random() * 60;\n                const depth = 12 + Math.random() * 12;\n\n                const boxGeo = new THREE.BoxGeometry(width, height, depth);\n                const boxMat = new THREE.MeshStandardMaterial({\n                    map: bldgTexture,\n                    roughness: 0.3,\n                    metalness: 0.8\n                });\n                const building = new THREE.Mesh(boxGeo, boxMat);\n                building.position.set(i * 14 + (Math.random() * 4 - 2), height / 2 - 4, -360 - Math.random() * 80);\n                skylineGroup.add(building);\n\n                // Rooftop laser spire\n                if (Math.random() < 0.6) {\n                    const spireHeight = 12 + Math.random() * 25;\n                    const spireGeo = new THREE.CylinderGeometry(0.12, 0.25, spireHeight, 8);\n                    const spireMat = new THREE.MeshBasicMaterial({\n                        color: Math.random() < 0.5 ? 0x00f3ff : 0xff0088\n                    });\n                    const spire = new THREE.Mesh(spireGeo, spireMat);\n                    spire.position.set(building.position.x, building.position.y + height / 2 + spireHeight / 2, building.position.z);\n                    skylineGroup.add(spire);\n                }\n            }\n            scene.add(skylineGroup);\n\n            // Starfield with Multi-color Cosmic Particles\n            const starGeo = new THREE.BufferGeometry();\n            const starCount = 900;\n            const starPos = new Float32Array(starCount * 3);\n            const starColors = new Float32Array(starCount * 3);\n\n            for (let i = 0; i < starCount * 3; i += 3) {\n                starPos[i] = (Math.random() - 0.5) * 800;\n                starPos[i + 1] = Math.random() * 200 + 10;\n                starPos[i + 2] = -Math.random() * 500 - 40;\n\n                const rChoice = Math.random();\n                if (rChoice < 0.4) {\n                    starColors[i] = 0.0; starColors[i + 1] = 0.95; starColors[i + 2] = 1.0;\n                } else if (rChoice < 0.7) {\n                    starColors[i] = 1.0; starColors[i + 1] = 0.4; starColors[i + 2] = 0.8;\n                } else {\n                    starColors[i] = 1.0; starColors[i + 1] = 0.9; starColors[i + 2] = 0.5;\n                }\n            }\n            starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));\n            starGeo.setAttribute('color', new THREE.BufferAttribute(starColors, 3));\n\n            const starMat = new THREE.PointsMaterial({\n                size: 1.6,\n                vertexColors: true,\n                transparent: true,\n                opacity: 0.9\n            });\n            starParticles = new THREE.Points(starGeo, starMat);\n            scene.add(starParticles);\n        }\n\n        function buildSearchlights() {\n            for (let i = 0; i < 3; i++) {\n                const light = new THREE.SpotLight(i === 0 ? 0x00f3ff : 0xff0088, 3.5, 400, Math.PI / 12, 0.4, 0.8);\n                light.position.set((i - 1) * 70, 0, -320);\n                const target = new THREE.Object3D();\n                target.position.set((i - 1) * 50, 120, -380);\n                scene.add(target);\n                light.target = target;\n                scene.add(light);\n                searchlightsArray.push({ light: light, target: target, baseAngle: i * 2.1 });\n            }\n        }\n\n        function buildHighwayRoad() {\n            const theme = THEMES[STATE.theme];\n            const normalMap = createAsphaltNormalMap();\n\n            const roadGeo = new THREE.PlaneGeometry(CONFIG.roadWidth, CONFIG.roadLength, 1, 120);\n            const roadMat = new THREE.MeshStandardMaterial({\n                color: 0x070414,\n                roughness: 0.16,\n                metalness: 0.88,\n                normalMap: normalMap,\n                normalScale: new THREE.Vector2(0.9, 0.9)\n            });\n            roadMesh = new THREE.Mesh(roadGeo, roadMat);\n            roadMesh.rotation.x = -Math.PI / 2;\n            roadMesh.position.set(0, 0, -CONFIG.roadLength / 2 + 20);\n            roadMesh.receiveShadow = true;\n            scene.add(roadMesh);\n\n            // Glowing Scrolling Highway Lane Lines\n            const laneSegments = 30;\n            const laneSpacing = CONFIG.roadLength / laneSegments;\n            const laneGroup = new THREE.Group();\n\n            for (let lane = 1; lane < CONFIG.laneCount; lane++) {\n                const laneX = (lane - 2.5) * (CONFIG.roadWidth / CONFIG.laneCount);\n                for (let s = 0; s < laneSegments; s++) {\n                    const stripeGeo = new THREE.PlaneGeometry(0.22, 5.5);\n                    const stripeMat = new THREE.MeshBasicMaterial({\n                        color: theme.laneGlow,\n                        transparent: true,\n                        opacity: 0.8\n                    });\n                    const stripe = new THREE.Mesh(stripeGeo, stripeMat);\n                    stripe.rotation.x = -Math.PI / 2;\n                    stripe.position.set(laneX, 0.02, -s * laneSpacing);\n                    laneGroup.add(stripe);\n                    laneLinesArray.push(stripe);\n                }\n            }\n            scene.add(laneGroup);\n\n            // Outer Neon Grid Helper\n            gridHelper = new THREE.GridHelper(260, 65, theme.grid, theme.grid);\n            gridHelper.position.set(0, -0.06, -100);\n            gridHelper.scale.set(1.6, 1, 2.2);\n            scene.add(gridHelper);\n\n            // Neon Glowing Guardrails\n            [-CONFIG.roadWidth / 2, CONFIG.roadWidth / 2].forEach(x => {\n                const railGeo = new THREE.BoxGeometry(0.45, 0.9, CONFIG.roadLength);\n                const railMat = new THREE.MeshStandardMaterial({\n                    color: 0x110e20,\n                    metalness: 0.9,\n                    roughness: 0.2\n                });\n                const rail = new THREE.Mesh(railGeo, railMat);\n                rail.position.set(x, 0.45, -CONFIG.roadLength / 2 + 20);\n                scene.add(rail);\n\n                // Neon neon strip on top of guardrail\n                const stripGeo = new THREE.BoxGeometry(0.18, 0.2, CONFIG.roadLength);\n                const stripMat = new THREE.MeshBasicMaterial({ color: theme.primary });\n                const neonStrip = new THREE.Mesh(stripGeo, stripMat);\n                neonStrip.position.set(x > 0 ? x - 0.15 : x + 0.15, 0.85, -CONFIG.roadLength / 2 + 20);\n                scene.add(neonStrip);\n            });\n        }\n\n        function buildPlayerCar() {\n            playerGroup = new THREE.Group();\n\n            // Pearlescent Automotive Paint\n            const paintMat = new THREE.MeshStandardMaterial({\n                color: 0xff4800,\n                metalness: 0.88,\n                roughness: 0.18\n            });\n\n            const carbonMat = new THREE.MeshStandardMaterial({\n                color: 0x12141c,\n                metalness: 0.85,\n                roughness: 0.32\n            });\n\n            const glassMat = new THREE.MeshStandardMaterial({\n                color: 0x060912,\n                metalness: 0.92,\n                roughness: 0.08,\n                transparent: true,\n                opacity: 0.92\n            });\n\n            const cyberNeonMat = new THREE.MeshBasicMaterial({ color: 0x00f3ff });\n            const tailGlowMat = new THREE.MeshBasicMaterial({ color: 0xff0044 });\n\n            // Hood and aerodynamic splitter\n            const noseGroup = new THREE.Group();\n            const hoodGeo = new THREE.BoxGeometry(1.72, 0.28, 1.8);\n            const hoodMesh = new THREE.Mesh(hoodGeo, paintMat);\n            hoodMesh.position.set(0, 0.38, -1.3);\n            hoodMesh.rotation.x = 0.08;\n            noseGroup.add(hoodMesh);\n\n            // Hood neon accent line\n            const hoodAccentGeo = new THREE.BoxGeometry(0.06, 0.04, 1.4);\n            const hoodAccent = new THREE.Mesh(hoodAccentGeo, cyberNeonMat);\n            hoodAccent.position.set(0, 0.54, -1.3);\n            hoodAccent.rotation.x = 0.08;\n            noseGroup.add(hoodAccent);\n\n            const hoodScoopGeo = new THREE.BoxGeometry(0.82, 0.1, 1.2);\n            const hoodScoop = new THREE.Mesh(hoodScoopGeo, carbonMat);\n            hoodScoop.position.set(0, 0.46, -1.2);\n            hoodScoop.rotation.x = 0.15;\n            noseGroup.add(hoodScoop);\n\n            const splitterGeo = new THREE.BoxGeometry(2.1, 0.08, 0.9);\n            const splitter = new THREE.Mesh(splitterGeo, carbonMat);\n            splitter.position.set(0, 0.12, -2.15);\n            noseGroup.add(splitter);\n\n            [-1.04, 1.04].forEach(x => {\n                const wingletGeo = new THREE.BoxGeometry(0.04, 0.3, 0.4);\n                const winglet = new THREE.Mesh(wingletGeo, carbonMat);\n                winglet.position.set(x, 0.22, -2.2);\n                winglet.rotation.z = x > 0 ? -0.15 : 0.15;\n                noseGroup.add(winglet);\n            });\n\n            [-0.96, 0.96].forEach(x => {\n                const archGeo = new THREE.CylinderGeometry(0.46, 0.48, 0.42, 16, 1, false, 0, Math.PI);\n                const arch = new THREE.Mesh(archGeo, paintMat);\n                arch.rotation.z = Math.PI / 2;\n                arch.rotation.y = x > 0 ? -Math.PI / 2 : Math.PI / 2;\n                arch.position.set(x, 0.45, -1.25);\n                arch.scale.set(1.0, 1.4, 0.85);\n                noseGroup.add(arch);\n            });\n\n            playerGroup.add(noseGroup);\n\n            // Cockpit Canopy\n            const canopyGeo = new THREE.SphereGeometry(0.85, 24, 16, 0, Math.PI * 2, 0, Math.PI * 0.55);\n            const canopy = new THREE.Mesh(canopyGeo, glassMat);\n            canopy.scale.set(1.15, 0.75, 2.1);\n            canopy.position.set(0, 0.52, -0.2);\n            playerGroup.add(canopy);\n\n            const roofScoopGeo = new THREE.BoxGeometry(0.38, 0.14, 1.1);\n            const roofScoop = new THREE.Mesh(roofScoopGeo, carbonMat);\n            roofScoop.position.set(0, 0.98, -0.1);\n            roofScoop.rotation.x = -0.05;\n            playerGroup.add(roofScoop);\n\n            const spineGeo = new THREE.BoxGeometry(0.7, 0.25, 1.8);\n            const spine = new THREE.Mesh(spineGeo, carbonMat);\n            spine.position.set(0, 0.75, 0.9);\n            spine.rotation.x = -0.12;\n            playerGroup.add(spine);\n\n            for (let z = 0.3; z <= 1.3; z += 0.25) {\n                const louverGeo = new THREE.BoxGeometry(0.65, 0.03, 0.12);\n                const louver = new THREE.Mesh(louverGeo, paintMat);\n                louver.position.set(0, 0.78 - z * 0.08, z);\n                louver.rotation.x = -0.25;\n                playerGroup.add(louver);\n            }\n\n            [-1.02, 1.02].forEach(x => {\n                const skirtGeo = new THREE.BoxGeometry(0.22, 0.12, 2.2);\n                const skirt = new THREE.Mesh(skirtGeo, carbonMat);\n                skirt.position.set(x, 0.14, -0.1);\n                playerGroup.add(skirt);\n\n                const ventGeo = new THREE.BoxGeometry(0.18, 0.38, 0.9);\n                const vent = new THREE.Mesh(ventGeo, carbonMat);\n                vent.position.set(x * 0.92, 0.42, 0.1);\n                playerGroup.add(vent);\n            });\n\n            [-1.06, 1.06].forEach(x => {\n                const hipGeo = new THREE.CylinderGeometry(0.52, 0.54, 0.48, 16, 1, false, 0, Math.PI);\n                const hip = new THREE.Mesh(hipGeo, paintMat);\n                hip.rotation.z = Math.PI / 2;\n                hip.rotation.y = x > 0 ? -Math.PI / 2 : Math.PI / 2;\n                hip.position.set(x, 0.52, 1.05);\n                hip.scale.set(1.0, 1.3, 0.95);\n                playerGroup.add(hip);\n            });\n\n            const rearDeckGeo = new THREE.BoxGeometry(1.5, 0.4, 1.6);\n            const rearDeck = new THREE.Mesh(rearDeckGeo, paintMat);\n            rearDeck.position.set(0, 0.52, 1.0);\n            playerGroup.add(rearDeck);\n\n            // Aerodynamic GT Wing with Cyber Endplates\n            const wingGroup = new THREE.Group();\n            [-0.35, 0.35].forEach(x => {\n                const strutGeo = new THREE.BoxGeometry(0.06, 0.65, 0.1);\n                const strut = new THREE.Mesh(strutGeo, carbonMat);\n                strut.position.set(x, 0.95, 1.45);\n                wingGroup.add(strut);\n            });\n\n            const wingBladeGeo = new THREE.BoxGeometry(2.35, 0.06, 0.55);\n            const wingBlade = new THREE.Mesh(wingBladeGeo, carbonMat);\n            wingBlade.position.set(0, 1.25, 1.8);\n            wingBlade.rotation.x = -0.06;\n            wingGroup.add(wingBlade);\n\n            [-1.18, 1.18].forEach(x => {\n                const finGeo = new THREE.BoxGeometry(0.04, 0.75, 0.65);\n                const fin = new THREE.Mesh(finGeo, paintMat);\n                fin.position.set(x, 1.18, 1.65);\n                wingGroup.add(fin);\n\n                // Endplate neon glow stripe\n                const finStripeGeo = new THREE.BoxGeometry(0.06, 0.04, 0.62);\n                const finStripe = new THREE.Mesh(finStripeGeo, cyberNeonMat);\n                finStripe.position.set(x, 1.55, 1.65);\n                wingGroup.add(finStripe);\n            });\n            playerGroup.add(wingGroup);\n\n            // Twin Dual Thruster Afterburners\n            [-0.32, 0.32].forEach(x => {\n                const thrusterGeo = new THREE.CylinderGeometry(0.18, 0.22, 0.4, 20);\n                const thruster = new THREE.Mesh(thrusterGeo, carbonMat);\n                thruster.rotation.x = Math.PI / 2;\n                thruster.position.set(x, 0.56, 1.82);\n                playerGroup.add(thruster);\n\n                // Inner Flame Cone (Animated in loop)\n                const flameGeo = new THREE.ConeGeometry(0.14, 0.7, 16);\n                const flameMat = new THREE.MeshBasicMaterial({\n                    color: 0xff5500,\n                    transparent: true,\n                    opacity: 0.85\n                });\n                const flame = new THREE.Mesh(flameGeo, flameMat);\n                flame.rotation.x = -Math.PI / 2;\n                flame.position.set(x, 0.56, 2.15);\n                playerGroup.add(flame);\n                exhaustFlames.push(flame);\n            });\n\n            // Cyber Neon Full-Width Tail Light Bar\n            const tailLightGeo = new THREE.BoxGeometry(2.1, 0.07, 0.08);\n            const tailLight = new THREE.Mesh(tailLightGeo, tailGlowMat);\n            tailLight.position.set(0, 0.52, 1.86);\n            playerGroup.add(tailLight);\n\n            // Front Dual Headlights & Forward Spotlights\n            [-0.75, 0.75].forEach(x => {\n                const mirrorGeo = new THREE.BoxGeometry(0.26, 0.1, 0.14);\n                const mirror = new THREE.Mesh(mirrorGeo, paintMat);\n                mirror.position.set(x > 0 ? 1.0 : -1.0, 0.76, -0.7);\n                playerGroup.add(mirror);\n\n                const hlGeo = new THREE.BoxGeometry(0.44, 0.08, 0.12);\n                const hl = new THREE.Mesh(hlGeo, cyberNeonMat);\n                hl.position.set(x, 0.38, -2.12);\n                hl.rotation.y = x > 0 ? -0.15 : 0.15;\n                playerGroup.add(hl);\n\n                // Real Spotlight casting forward light on road\n                const spot = new THREE.SpotLight(0x00f3ff, 2.2, 50, Math.PI / 5, 0.4, 1);\n                spot.position.set(x, 0.4, -2.2);\n                const spotTarget = new THREE.Object3D();\n                spotTarget.position.set(x, 0, -35);\n                playerGroup.add(spotTarget);\n                spot.target = spotTarget;\n                playerGroup.add(spot);\n            });\n\n            // Realistic High-Tech Wheels\n            const wheelPositions = [\n                [-1.04, 0.36, -1.25, 0.36, 0.32],\n                [ 1.04, 0.36, -1.25, 0.36, 0.32],\n                [-1.10, 0.40,  1.05, 0.40, 0.38],\n                [ 1.10, 0.40,  1.05, 0.40, 0.38]\n            ];\n\n            wheelPositions.forEach((pos) => {\n                const [wX, wY, wZ, radius, width] = pos;\n                const wheelGroup = new THREE.Group();\n\n                const tireGeo = new THREE.CylinderGeometry(radius, radius, width, 24);\n                const tireMat = new THREE.MeshStandardMaterial({ color: 0x090a0d, roughness: 0.85 });\n                const tire = new THREE.Mesh(tireGeo, tireMat);\n                tire.rotation.z = Math.PI / 2;\n                wheelGroup.add(tire);\n\n                const rimGeo = new THREE.CylinderGeometry(radius * 0.78, radius * 0.78, width + 0.02, 20);\n                const rimMat = new THREE.MeshStandardMaterial({ color: 0x161822, metalness: 0.95, roughness: 0.15 });\n                const rim = new THREE.Mesh(rimGeo, rimMat);\n                rim.rotation.z = Math.PI / 2;\n                wheelGroup.add(rim);\n\n                for (let s = 0; s < 5; s++) {\n                    const spokeAngle = (s * Math.PI * 2) / 5;\n                    const spokeGeo = new THREE.BoxGeometry(radius * 1.35, width + 0.03, 0.05);\n                    const spoke = new THREE.Mesh(spokeGeo, rimMat);\n                    spoke.rotation.x = spokeAngle;\n                    spoke.rotation.z = Math.PI / 2;\n                    wheelGroup.add(spoke);\n                }\n\n                // Glowing neon rim lip\n                const rimLipGeo = new THREE.TorusGeometry(radius * 0.76, 0.02, 8, 24);\n                const rimLip = new THREE.Mesh(rimLipGeo, cyberNeonMat);\n                rimLip.rotation.y = Math.PI / 2;\n                rimLip.position.set(wX > 0 ? width / 2 : -width / 2, 0, 0);\n                wheelGroup.add(rimLip);\n\n                wheelGroup.position.set(wX, wY, wZ);\n                playerGroup.add(wheelGroup);\n                wheelMeshes.push(wheelGroup);\n            });\n\n            // Dynamic Real Underglow PointLight\n            underglowLight = new THREE.PointLight(0xff4400, 3.2, 8);\n            underglowLight.position.set(0, 0.15, 0);\n            playerGroup.add(underglowLight);\n\n            // Underglow Plane\n            const glowGeo = new THREE.PlaneGeometry(2.8, 5.0);\n            const underglowMat = new THREE.MeshBasicMaterial({\n                color: 0xff5500,\n                transparent: true,\n                opacity: 0.7,\n                depthWrite: false\n            });\n            const underglow = new THREE.Mesh(glowGeo, underglowMat);\n            underglow.rotation.x = -Math.PI / 2;\n            underglow.position.set(0, 0.04, -0.1);\n            playerGroup.add(underglow);\n\n            playerGroup.position.set(0, 0, 0);\n            scene.add(playerGroup);\n        }\n\n        function buildEnvironmentProps() {\n            for (let z = -360; z <= 40; z += 60) {\n                spawnHighwayArch(z);\n            }\n        }\n\n        function spawnHighwayArch(zPos) {\n            const archGroup = new THREE.Group();\n            const theme = THEMES[STATE.theme];\n\n            const archGeo = new THREE.BoxGeometry(CONFIG.roadWidth + 4, 0.5, 0.5);\n            const archMat = new THREE.MeshStandardMaterial({\n                color: 0x141028,\n                metalness: 0.8,\n                roughness: 0.3\n            });\n            const topBar = new THREE.Mesh(archGeo, archMat);\n            topBar.position.y = 8;\n            archGroup.add(topBar);\n\n            // Overhead Electronic Signboard\n            const signGeo = new THREE.PlaneGeometry(10, 2.2);\n            const signCanvas = document.createElement('canvas');\n            signCanvas.width = 256; signCanvas.height = 64;\n            const sCtx = signCanvas.getContext('2d');\n            sCtx.fillStyle = '#050212';\n            sCtx.fillRect(0, 0, 256, 64);\n            sCtx.strokeStyle = '#00f3ff';\n            sCtx.lineWidth = 4;\n            sCtx.strokeRect(2, 2, 252, 60);\n            sCtx.fillStyle = '#ffaa00';\n            sCtx.font = 'bold 20px Orbitron, sans-serif';\n            sCtx.textAlign = 'center';\n            sCtx.fillText('ROUTE 99 · NEO VELOCITY', 128, 38);\n\n            const signTex = new THREE.CanvasTexture(signCanvas);\n            const signMat = new THREE.MeshBasicMaterial({ map: signTex });\n            const signMesh = new THREE.Mesh(signGeo, signMat);\n            signMesh.position.set(0, 8, -0.3);\n            archGroup.add(signMesh);\n\n            [-CONFIG.roadWidth / 2 - 2, CONFIG.roadWidth / 2 + 2].forEach(x => {\n                const poleGeo = new THREE.BoxGeometry(0.5, 8, 0.5);\n                const pole = new THREE.Mesh(poleGeo, archMat);\n                pole.position.set(x, 4, 0);\n                archGroup.add(pole);\n\n                const neonStripGeo = new THREE.BoxGeometry(0.12, 8, 0.12);\n                const neonStrip = new THREE.Mesh(neonStripGeo, new THREE.MeshBasicMaterial({ color: theme.secondary }));\n                neonStrip.position.set(x > 0 ? x - 0.25 : x + 0.25, 4, 0);\n                archGroup.add(neonStrip);\n            });\n\n            archGroup.position.z = zPos;\n            scene.add(archGroup);\n            sceneryArray.push(archGroup);\n        }\n\n        function buildSpeedLines() {\n            speedLinesGroup = new THREE.Group();\n            const lineCount = 90;\n            const lineGeo = new THREE.BufferGeometry();\n            const positions = new Float32Array(lineCount * 6);\n\n            for (let i = 0; i < lineCount * 6; i += 6) {\n                const x = (Math.random() - 0.5) * 32;\n                const y = Math.random() * 9 + 0.5;\n                const z = -Math.random() * 120;\n\n                positions[i] = x;\n                positions[i + 1] = y;\n                positions[i + 2] = z;\n\n                positions[i + 3] = x;\n                positions[i + 4] = y;\n                positions[i + 5] = z - 6;\n            }\n\n            lineGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));\n            const lineMat = new THREE.LineBasicMaterial({\n                color: 0x00f3ff,\n                transparent: true,\n                opacity: 0.5\n            });\n\n            speedLinesGroup.add(new THREE.LineSegments(lineGeo, lineMat));\n            scene.add(speedLinesGroup);\n        }\n\n        function spawnTraffic() {\n            if (trafficArray.length >= 6) return;\n\n            const laneIndex = Math.floor(Math.random() * CONFIG.laneCount);\n            const laneX = (laneIndex - 2) * (CONFIG.roadWidth / CONFIG.laneCount);\n            const type = Math.floor(Math.random() * 4); // 0: Cyber GT, 1: Titan Hauler, 2: Valkyrie Hover, 3: Neo Enforcer\n\n            const trafficGroup = new THREE.Group();\n            const wheels = [];\n            let speed = 0.32;\n            let isHover = false;\n            let repulsors = [];\n            let isPolice = false;\n            let policeLight = null, strobeRed = null, strobeBlue = null;\n\n            if (type === 0) {\n                // TYPE 0: APEX CYBER GT (Low-slung Sleek Cyber Sportscar)\n                speed = 0.34;\n                const paintMat = new THREE.MeshStandardMaterial({ color: 0x0a1628, metalness: 0.92, roughness: 0.18 });\n                const carbonMat = new THREE.MeshStandardMaterial({ color: 0x12141c, metalness: 0.85, roughness: 0.35 });\n                const neonCyanMat = new THREE.MeshBasicMaterial({ color: 0x00f3ff });\n\n                // Sleek Chassis\n                const bodyGeo = new THREE.BoxGeometry(1.68, 0.45, 3.8);\n                const body = new THREE.Mesh(bodyGeo, paintMat);\n                body.position.y = 0.35;\n                trafficGroup.add(body);\n\n                // Aerodynamic Cockpit Dome\n                const canopyGeo = new THREE.CylinderGeometry(0.55, 0.72, 1.6, 12);\n                const canopyMat = new THREE.MeshStandardMaterial({ color: 0x060a14, metalness: 0.95, roughness: 0.08 });\n                const canopy = new THREE.Mesh(canopyGeo, canopyMat);\n                canopy.rotation.x = Math.PI / 2;\n                canopy.position.set(0, 0.65, 0.1);\n                trafficGroup.add(canopy);\n\n                // Front carbon splitter & hood neon vent\n                const splitterGeo = new THREE.BoxGeometry(1.72, 0.06, 0.8);\n                const splitter = new THREE.Mesh(splitterGeo, carbonMat);\n                splitter.position.set(0, 0.16, -1.8);\n                trafficGroup.add(splitter);\n\n                const hoodStripGeo = new THREE.BoxGeometry(0.06, 0.04, 1.2);\n                const hoodStrip = new THREE.Mesh(hoodStripGeo, neonCyanMat);\n                hoodStrip.position.set(0, 0.58, -1.1);\n                trafficGroup.add(hoodStrip);\n\n                // Rear GT Wing with glowing cyan endplates\n                const wingBladeGeo = new THREE.BoxGeometry(1.8, 0.05, 0.35);\n                const wingBlade = new THREE.Mesh(wingBladeGeo, carbonMat);\n                wingBlade.position.set(0, 0.88, 1.65);\n                trafficGroup.add(wingBlade);\n\n                [-0.9, 0.9].forEach(x => {\n                    const finGeo = new THREE.BoxGeometry(0.04, 0.3, 0.4);\n                    const fin = new THREE.Mesh(finGeo, neonCyanMat);\n                    fin.position.set(x, 0.88, 1.65);\n                    trafficGroup.add(fin);\n                });\n\n                // Front dual piercing headlights & Rear horizontal neon tail light\n                const hlGeo = new THREE.BoxGeometry(1.4, 0.06, 0.08);\n                const hl = new THREE.Mesh(hlGeo, new THREE.MeshBasicMaterial({ color: 0xffffff }));\n                hl.position.set(0, 0.35, -1.91);\n                trafficGroup.add(hl);\n\n                const tlGeo = new THREE.BoxGeometry(1.5, 0.07, 0.08);\n                const tl = new THREE.Mesh(tlGeo, new THREE.MeshBasicMaterial({ color: 0x00f3ff }));\n                tl.position.set(0, 0.42, 1.91);\n                trafficGroup.add(tl);\n\n                // 4 Detailed Wheels with glowing cyan rims\n                const wheelPositions = [\n                    [-0.88, 0.3, -1.1], [0.88, 0.3, -1.1],\n                    [-0.88, 0.32, 1.1], [0.88, 0.32, 1.1]\n                ];\n                wheelPositions.forEach(pos => {\n                    const wGroup = new THREE.Group();\n                    const tire = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.3, 0.22, 16), new THREE.MeshStandardMaterial({ color: 0x0b0c10, roughness: 0.8 }));\n                    tire.rotation.z = Math.PI / 2;\n                    wGroup.add(tire);\n                    const rim = new THREE.Mesh(new THREE.TorusGeometry(0.2, 0.02, 6, 16), neonCyanMat);\n                    rim.rotation.y = Math.PI / 2;\n                    rim.position.x = pos[0] > 0 ? 0.11 : -0.11;\n                    wGroup.add(rim);\n                    wGroup.position.set(pos[0], pos[1], pos[2]);\n                    trafficGroup.add(wGroup);\n                    wheels.push(wGroup);\n                });\n\n                // Cyan Underglow\n                const under = new THREE.PointLight(0x00f3ff, 1.8, 8);\n                under.position.set(0, 0.15, 0);\n                trafficGroup.add(under);\n\n            } else if (type === 1) {\n                // TYPE 1: TITAN CYBER HAULER (Massive Armored Cyber Rig / Heavy Truck)\n                speed = 0.18;\n                const haulerPaintMat = new THREE.MeshStandardMaterial({ color: 0x181420, metalness: 0.88, roughness: 0.3 });\n                const amberNeonMat = new THREE.MeshBasicMaterial({ color: 0xffaa00 });\n\n                // Cab Cabin\n                const cabGeo = new THREE.BoxGeometry(1.9, 1.6, 1.8);\n                const cab = new THREE.Mesh(cabGeo, haulerPaintMat);\n                cab.position.set(0, 1.1, -1.7);\n                trafficGroup.add(cab);\n\n                // Armored Visor Windshield\n                const visorGeo = new THREE.BoxGeometry(1.75, 0.45, 0.3);\n                const visor = new THREE.Mesh(visorGeo, new THREE.MeshStandardMaterial({ color: 0x0a0d18, metalness: 0.95, roughness: 0.1 }));\n                visor.position.set(0, 1.35, -2.55);\n                trafficGroup.add(visor);\n\n                // Huge Cargo Trailer\n                const trailerGeo = new THREE.BoxGeometry(2.0, 1.9, 3.8);\n                const trailer = new THREE.Mesh(trailerGeo, new THREE.MeshStandardMaterial({ color: 0x0f0c18, metalness: 0.85, roughness: 0.25 }));\n                trailer.position.set(0, 1.25, 0.9);\n                trafficGroup.add(trailer);\n\n                // Trailer Hazard Chevron Accent Stripes\n                [-1.02, 1.02].forEach(x => {\n                    const stripeGeo = new THREE.BoxGeometry(0.04, 0.12, 3.4);\n                    const stripe = new THREE.Mesh(stripeGeo, amberNeonMat);\n                    stripe.position.set(x, 1.6, 0.9);\n                    trafficGroup.add(stripe);\n                });\n\n                // Dual Vertical Smoke Stacks\n                [-0.95, 0.95].forEach(x => {\n                    const pipeGeo = new THREE.CylinderGeometry(0.08, 0.08, 1.8, 12);\n                    const pipe = new THREE.Mesh(pipeGeo, new THREE.MeshStandardMaterial({ color: 0x555566, metalness: 0.95, roughness: 0.1 }));\n                    pipe.position.set(x, 1.8, -0.9);\n                    trafficGroup.add(pipe);\n\n                    const heatRing = new THREE.Mesh(new THREE.TorusGeometry(0.1, 0.03, 6, 12), new THREE.MeshBasicMaterial({ color: 0xff4400 }));\n                    heatRing.rotation.x = Math.PI / 2;\n                    heatRing.position.set(x, 2.65, -0.9);\n                    trafficGroup.add(heatRing);\n                });\n\n                // Rear Heavy Brake Light Strip\n                const rearLightGeo = new THREE.BoxGeometry(1.8, 0.12, 0.08);\n                const rearLight = new THREE.Mesh(rearLightGeo, new THREE.MeshBasicMaterial({ color: 0xff2200 }));\n                rearLight.position.set(0, 0.5, 2.82);\n                trafficGroup.add(rearLight);\n\n                // 6 Heavy Wheels\n                const haulerWheelPos = [\n                    [-0.98, 0.38, -1.8], [0.98, 0.38, -1.8],\n                    [-1.02, 0.42, 0.8],  [1.02, 0.42, 0.8],\n                    [-1.02, 0.42, 2.0],  [1.02, 0.42, 2.0]\n                ];\n                haulerWheelPos.forEach(pos => {\n                    const wGroup = new THREE.Group();\n                    const tire = new THREE.Mesh(new THREE.CylinderGeometry(pos[1], pos[1], 0.28, 16), new THREE.MeshStandardMaterial({ color: 0x090a0e, roughness: 0.9 }));\n                    tire.rotation.z = Math.PI / 2;\n                    wGroup.add(tire);\n                    wGroup.position.set(pos[0], pos[1], pos[2]);\n                    trafficGroup.add(wGroup);\n                    wheels.push(wGroup);\n                });\n\n                // Amber Glow\n                const under = new THREE.PointLight(0xffaa00, 2.2, 9);\n                under.position.set(0, 0.25, 0.5);\n                trafficGroup.add(under);\n\n            } else if (type === 2) {\n                // TYPE 2: VALKYRIE ANTI-GRAV HOVERCRAFT (Floating Mag-Lev Speeder - NO WHEELS)\n                isHover = true;\n                speed = 0.45;\n                const stealthMat = new THREE.MeshStandardMaterial({ color: 0x140620, metalness: 0.92, roughness: 0.15 });\n                const magentaMat = new THREE.MeshBasicMaterial({ color: 0xff0088 });\n\n                // Delta-wing Aerodynamic Body\n                const fuselageGeo = new THREE.BoxGeometry(1.8, 0.32, 3.4);\n                const fuselage = new THREE.Mesh(fuselageGeo, stealthMat);\n                fuselage.position.y = 0.4;\n                trafficGroup.add(fuselage);\n\n                // Pointed Nose Cone\n                const noseGeo = new THREE.ConeGeometry(0.9, 1.4, 4);\n                const nose = new THREE.Mesh(noseGeo, stealthMat);\n                nose.rotation.x = -Math.PI / 2;\n                nose.rotation.y = Math.PI / 4;\n                nose.position.set(0, 0.4, -2.1);\n                trafficGroup.add(nose);\n\n                // Twin Angled Vertical Stabilizer Fins\n                [-0.85, 0.85].forEach(x => {\n                    const finGeo = new THREE.BoxGeometry(0.05, 0.65, 0.9);\n                    const fin = new THREE.Mesh(finGeo, stealthMat);\n                    fin.position.set(x, 0.65, 1.1);\n                    fin.rotation.z = x > 0 ? 0.2 : -0.2;\n                    trafficGroup.add(fin);\n\n                    const finStripe = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.05, 0.85), magentaMat);\n                    finStripe.position.set(x, 0.95, 1.1);\n                    trafficGroup.add(finStripe);\n                });\n\n                // 4 Corner Magnetic Repulsor Turbine Rings (Spinning)\n                const repulsorPositions = [\n                    [-0.95, 0.3, -1.0], [0.95, 0.3, -1.0],\n                    [-0.95, 0.3,  1.1], [0.95, 0.3,  1.1]\n                ];\n                repulsorPositions.forEach(pos => {\n                    const rGroup = new THREE.Group();\n                    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.04, 8, 16), magentaMat);\n                    ring.rotation.x = Math.PI / 2;\n                    rGroup.add(ring);\n                    rGroup.position.set(pos[0], pos[1], pos[2]);\n                    trafficGroup.add(rGroup);\n                    repulsors.push(rGroup);\n                });\n\n                // Dual Glowing Ion Thruster Nozzles at Rear\n                [-0.45, 0.45].forEach(x => {\n                    const jetGeo = new THREE.CylinderGeometry(0.16, 0.22, 0.3, 16);\n                    const jet = new THREE.Mesh(jetGeo, magentaMat);\n                    jet.rotation.x = Math.PI / 2;\n                    jet.position.set(x, 0.4, 1.72);\n                    trafficGroup.add(jet);\n                });\n\n                // Rear Neon Tail Strip\n                const tailGeo = new THREE.BoxGeometry(1.6, 0.07, 0.08);\n                const tail = new THREE.Mesh(tailGeo, magentaMat);\n                tail.position.set(0, 0.48, 1.71);\n                trafficGroup.add(tail);\n\n                // Magenta Hover Glow\n                const under = new THREE.PointLight(0xff0088, 2.5, 9);\n                under.position.set(0, 0.2, 0);\n                trafficGroup.add(under);\n\n            } else {\n                // TYPE 3: NEO-TOKYO POLICE ENFORCER (Patrol Interceptor with Alternating Red & Blue Strobe Lightbar)\n                isPolice = true;\n                speed = 0.38;\n                const policeMat = new THREE.MeshStandardMaterial({ color: 0x080c16, metalness: 0.9, roughness: 0.2 });\n                const carbonMat = new THREE.MeshStandardMaterial({ color: 0x12141c, metalness: 0.85, roughness: 0.35 });\n\n                // Aggressive Body\n                const bodyGeo = new THREE.BoxGeometry(1.7, 0.5, 3.7);\n                const body = new THREE.Mesh(bodyGeo, policeMat);\n                body.position.y = 0.38;\n                trafficGroup.add(body);\n\n                // White Cyber Decal Side Stripe\n                [-0.86, 0.86].forEach(x => {\n                    const decal = new THREE.Mesh(new THREE.PlaneGeometry(2.6, 0.15), new THREE.MeshBasicMaterial({ color: 0xffffff }));\n                    decal.rotation.y = x > 0 ? Math.PI / 2 : -Math.PI / 2;\n                    decal.position.set(x, 0.4, 0);\n                    trafficGroup.add(decal);\n                });\n\n                // Roof Emergency Lightbar (Red & Blue Strobe)\n                const barBase = new THREE.Mesh(new THREE.BoxGeometry(1.1, 0.08, 0.25), carbonMat);\n                barBase.position.set(0, 0.82, 0.1);\n                trafficGroup.add(barBase);\n\n                strobeRed = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.1, 0.22), new THREE.MeshBasicMaterial({ color: 0xff0022, transparent: true, opacity: 1 }));\n                strobeRed.position.set(-0.27, 0.88, 0.1);\n                trafficGroup.add(strobeRed);\n\n                strobeBlue = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.1, 0.22), new THREE.MeshBasicMaterial({ color: 0x0066ff, transparent: true, opacity: 1 }));\n                strobeBlue.position.set(0.27, 0.88, 0.1);\n                trafficGroup.add(strobeBlue);\n\n                // Front Heavy Ramming Push-Bumper\n                const bumperGeo = new THREE.BoxGeometry(1.6, 0.25, 0.15);\n                const bumper = new THREE.Mesh(bumperGeo, carbonMat);\n                bumper.position.set(0, 0.28, -1.9);\n                trafficGroup.add(bumper);\n\n                // Front Piercing Xenon Headlights & Rear Lights\n                const hl = new THREE.Mesh(new THREE.BoxGeometry(1.3, 0.08, 0.08), new THREE.MeshBasicMaterial({ color: 0xffffff }));\n                hl.position.set(0, 0.42, -1.86);\n                trafficGroup.add(hl);\n\n                const tl = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.08, 0.08), new THREE.MeshBasicMaterial({ color: 0xff0033 }));\n                tl.position.set(0, 0.45, 1.86);\n                trafficGroup.add(tl);\n\n                // Wheels\n                const policeWheelPos = [\n                    [-0.88, 0.32, -1.1], [0.88, 0.32, -1.1],\n                    [-0.88, 0.32,  1.1], [0.88, 0.32,  1.1]\n                ];\n                policeWheelPos.forEach(pos => {\n                    const wGroup = new THREE.Group();\n                    const tire = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.22, 16), new THREE.MeshStandardMaterial({ color: 0x090a0e, roughness: 0.85 }));\n                    tire.rotation.z = Math.PI / 2;\n                    wGroup.add(tire);\n                    wGroup.position.set(pos[0], pos[1], pos[2]);\n                    trafficGroup.add(wGroup);\n                    wheels.push(wGroup);\n                });\n\n                // Flashing Police Strobe Light\n                policeLight = new THREE.PointLight(0xff0022, 2.2, 9);\n                policeLight.position.set(0, 1.0, 0.1);\n                trafficGroup.add(policeLight);\n            }\n\n            trafficGroup.position.set(laneX, 0, CONFIG.trafficSpawnDist - Math.random() * 40);\n            trafficGroup.userData = {\n                speed: speed,\n                lane: laneIndex,\n                passed: false,\n                wheels: wheels,\n                isHover: isHover,\n                repulsors: repulsors,\n                isPolice: isPolice,\n                policeLight: policeLight,\n                strobeRed: strobeRed,\n                strobeBlue: strobeBlue,\n                seed: Math.random() * 10\n            };\n\n            scene.add(trafficGroup);\n            trafficArray.push(trafficGroup);\n        }\n\n        // Spawn Floating Cyber Power Prisms\n        function spawnCollectible() {\n            if (collectibleArray.length >= 3) return;\n\n            const laneIndex = Math.floor(Math.random() * CONFIG.laneCount);\n            const laneX = (laneIndex - 2) * (CONFIG.roadWidth / CONFIG.laneCount);\n            const isShield = Math.random() < 0.25;\n\n            const group = new THREE.Group();\n\n            if (isShield) {\n                // Spherical Holo-Shield\n                const geo = new THREE.IcosahedronGeometry(0.7, 1);\n                const mat = new THREE.MeshBasicMaterial({ color: 0x00f3ff, wireframe: true });\n                const core = new THREE.Mesh(geo, mat);\n                group.add(core);\n\n                const ringGeo = new THREE.TorusGeometry(0.9, 0.03, 8, 24);\n                const ring = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({ color: 0x00f3ff }));\n                group.add(ring);\n                group.userData = { type: 'shield', core: core, ring: ring };\n            } else {\n                // Polyhedral Glowing Power Crystal with Outer Ring\n                const geo = new THREE.OctahedronGeometry(0.65, 0);\n                const mat = new THREE.MeshStandardMaterial({\n                    color: 0xffaa00,\n                    emissive: 0xff6600,\n                    emissiveIntensity: 0.8,\n                    roughness: 0.1,\n                    metalness: 0.9\n                });\n                const core = new THREE.Mesh(geo, mat);\n                group.add(core);\n\n                const ringGeo = new THREE.TorusGeometry(0.85, 0.025, 8, 24);\n                const ring = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({ color: 0xffbb00 }));\n                ring.rotation.x = Math.PI / 4;\n                group.add(ring);\n                group.userData = { type: 'cube', core: core, ring: ring };\n            }\n\n            group.position.set(laneX, 1.3, CONFIG.trafficSpawnDist - Math.random() * 60);\n            scene.add(group);\n            collectibleArray.push(group);\n        }\n\n        const keys = {};\n\n        window.addEventListener('keydown', function(e) {\n            keys[e.code] = true;\n            if (e.code === 'Space') e.preventDefault();\n            if (e.code === 'KeyC') switchCameraView();\n        });\n        window.addEventListener('keyup', function(e) {\n            keys[e.code] = false;\n        });\n\n        const steerLeftBtn = document.getElementById('btn-steer-left');\n        if (steerLeftBtn) {\n            steerLeftBtn.addEventListener('touchstart', function(e) { e.preventDefault(); keys['ArrowLeft'] = true; });\n            steerLeftBtn.addEventListener('touchend', function(e) { e.preventDefault(); keys['ArrowLeft'] = false; });\n        }\n        const steerRightBtn = document.getElementById('btn-steer-right');\n        if (steerRightBtn) {\n            steerRightBtn.addEventListener('touchstart', function(e) { e.preventDefault(); keys['ArrowRight'] = true; });\n            steerRightBtn.addEventListener('touchend', function(e) { e.preventDefault(); keys['ArrowRight'] = false; });\n        }\n\n        function updatePlayer(delta, elapsed) {\n            const steerSpeed = 17.0;\n            if (keys['KeyA'] || keys['ArrowLeft']) {\n                STATE.targetPlayerX -= steerSpeed * delta;\n                STATE.playerRoll = Math.min(STATE.playerRoll + 2.8 * delta, 0.32);\n            } else if (keys['KeyD'] || keys['ArrowRight']) {\n                STATE.targetPlayerX += steerSpeed * delta;\n                STATE.playerRoll = Math.max(STATE.playerRoll - 2.8 * delta, -0.32);\n            } else {\n                STATE.playerRoll *= 0.84;\n            }\n\n            const maxX = CONFIG.roadWidth / 2 - 1.3;\n            STATE.targetPlayerX = Math.max(-maxX, Math.min(maxX, STATE.targetPlayerX));\n            STATE.playerX += (STATE.targetPlayerX - STATE.playerX) * 12.5 * delta;\n\n            // Nitro Boost Effects\n            if (keys['Space'] && STATE.nitroLevel > 5) {\n                if (!STATE.nitroActive) soundFX.playNitro();\n                STATE.nitroActive = true;\n                STATE.nitroLevel = Math.max(0, STATE.nitroLevel - 35 * delta);\n                STATE.targetSpeed = CONFIG.maxSpeed * CONFIG.nitroSpeedMultiplier;\n                \n                const speedLayer = document.getElementById('speed-layer');\n                if (speedLayer) speedLayer.style.opacity = '1';\n                const blurLayer = document.getElementById('nitro-blur-layer');\n                if (blurLayer) blurLayer.style.opacity = '1';\n\n                camera.fov += (80 - camera.fov) * 6.0 * delta;\n                camera.updateProjectionMatrix();\n\n                if (underglowLight) {\n                    underglowLight.color.setHex(0x00f3ff);\n                    underglowLight.intensity = 5.0;\n                }\n\n                // Exhaust supersonic flame scaling\n                exhaustFlames.forEach(f => {\n                    f.scale.set(1.4, 2.2 + Math.random() * 0.6, 1.4);\n                    f.material.color.setHex(0x00f3ff);\n                });\n\n                // Nitro spark particles\n                const sparkGeo = new THREE.BoxGeometry(0.12, 0.12, 0.4);\n                const sparkMat = new THREE.MeshBasicMaterial({ color: 0x00f3ff, transparent: true, opacity: 1 });\n                const spark = new THREE.Mesh(sparkGeo, sparkMat);\n                spark.position.set(STATE.playerX + (Math.random() - 0.5) * 0.5, 0.56, playerGroup.position.z + 1.9);\n                spark.userData.velocity = new THREE.Vector3((Math.random() - 0.5) * 0.15, (Math.random() - 0.5) * 0.15, Math.random() * 0.6 + 0.3);\n                scene.add(spark);\n                particlesArray.push(spark);\n\n            } else {\n                if (STATE.nitroActive) soundFX.playBlowOffValve();\n                STATE.nitroActive = false;\n                STATE.nitroLevel = Math.min(100, STATE.nitroLevel + 14 * delta);\n                STATE.targetSpeed = CONFIG.baseSpeed;\n                \n                const speedLayer = document.getElementById('speed-layer');\n                if (speedLayer) speedLayer.style.opacity = '0';\n                const blurLayer = document.getElementById('nitro-blur-layer');\n                if (blurLayer) blurLayer.style.opacity = '0';\n\n                camera.fov += (65 - camera.fov) * 5.0 * delta;\n                camera.updateProjectionMatrix();\n\n                if (underglowLight) {\n                    underglowLight.color.setHex(0xff4400);\n                    underglowLight.intensity = 3.2;\n                }\n\n                // Normal exhaust flame pulsing\n                exhaustFlames.forEach(f => {\n                    const flamePulse = 0.8 + Math.sin(elapsed * 25) * 0.2;\n                    f.scale.set(0.9, flamePulse, 0.9);\n                    f.material.color.setHex(0xff5500);\n                });\n            }\n\n            STATE.speed += (STATE.targetSpeed - STATE.speed) * 3.5 * delta;\n            STATE.kmh = Math.round(STATE.speed * 170);\n            if (STATE.kmh > STATE.topKmh) STATE.topKmh = STATE.kmh;\n\n            playerGroup.position.x = STATE.playerX;\n            playerGroup.rotation.z = -STATE.playerRoll;\n            playerGroup.rotation.y = -STATE.playerRoll * 0.45;\n\n            // Rotate wheels based on vehicle velocity\n            wheelMeshes.forEach(w => {\n                w.rotation.x += STATE.speed * 40 * delta;\n            });\n\n            // Camera engine vibration\n            const speedRatio = STATE.speed / CONFIG.maxSpeed;\n            updateCameraPosition();\n            if (STATE.cameraMode === 0) {\n                camera.position.y += Math.sin(elapsed * 45) * 0.015 * speedRatio;\n                camera.position.x += Math.cos(elapsed * 30) * 0.01 * speedRatio;\n            }\n\n            soundFX.updateEngine(speedRatio);\n        }\n\n        function updateWorld(delta, elapsed) {\n            const moveDist = STATE.speed * 62 * delta;\n            STATE.distance += Math.round(moveDist);\n\n            const curveToggle = document.getElementById('toggle-curve');\n            if (curveToggle && curveToggle.checked) {\n                STATE.targetCurveFactor = Math.sin(STATE.distance * 0.0007) * 1.6;\n            } else {\n                STATE.targetCurveFactor = 0;\n            }\n            STATE.curveFactor += (STATE.targetCurveFactor - STATE.curveFactor) * delta;\n\n            // Scroll Highway Dashed Lane Lines\n            laneLinesArray.forEach(stripe => {\n                stripe.position.z += moveDist;\n                if (stripe.position.z > 20) {\n                    stripe.position.z -= CONFIG.roadLength;\n                }\n            });\n\n            // Scenery Gantries\n            sceneryArray.forEach(function(obj) {\n                obj.position.z += moveDist;\n                const zDist = Math.max(0, -obj.position.z);\n                obj.position.x = STATE.curveFactor * (zDist * zDist * 0.00015);\n\n                if (obj.position.z > 20) {\n                    obj.position.z -= 400;\n                }\n            });\n\n            // Searchlight Sweeping Animation\n            searchlightsArray.forEach(item => {\n                item.target.position.x = Math.sin(elapsed * 0.8 + item.baseAngle) * 90;\n                item.target.position.y = 110 + Math.cos(elapsed * 0.6 + item.baseAngle) * 30;\n            });\n\n            // Traffic Vehicles\n            for (let i = trafficArray.length - 1; i >= 0; i--) {\n                const car = trafficArray[i];\n                car.position.z += (moveDist - car.userData.speed * 30 * delta);\n\n                const zDist = Math.max(0, -car.position.z);\n                car.position.x = (car.userData.lane - 2) * (CONFIG.roadWidth / CONFIG.laneCount) + STATE.curveFactor * (zDist * zDist * 0.00015);\n\n                // Dynamic wheel rotation for rolling cars\n                if (car.userData.wheels && car.userData.wheels.length > 0) {\n                    for (let w = 0; w < car.userData.wheels.length; w++) {\n                        car.userData.wheels[w].rotation.x += car.userData.speed * 45 * delta;\n                    }\n                }\n\n                // Dynamic hover floating & repulsor spinning for hovercraft\n                if (car.userData.isHover) {\n                    car.position.y = 0.4 + Math.sin(elapsed * 5.5 + car.userData.seed) * 0.12;\n                    if (car.userData.repulsors) {\n                        for (let r = 0; r < car.userData.repulsors.length; r++) {\n                            car.userData.repulsors[r].rotation.z += 9.0 * delta;\n                        }\n                    }\n                }\n\n                // Police emergency strobe light flashing\n                if (car.userData.isPolice && car.userData.policeLight) {\n                    const strobeState = Math.floor(elapsed * 12) % 2 === 0;\n                    car.userData.policeLight.color.setHex(strobeState ? 0xff0022 : 0x0066ff);\n                    if (car.userData.strobeRed && car.userData.strobeBlue) {\n                        car.userData.strobeRed.material.opacity = strobeState ? 1.0 : 0.15;\n                        car.userData.strobeBlue.material.opacity = strobeState ? 0.15 : 1.0;\n                    }\n                }\n\n                if (!car.userData.passed && car.position.z > playerGroup.position.z + 2) {\n                    car.userData.passed = true;\n                    STATE.dodgedTraffic++;\n                    STATE.multiplier = Math.min(8.0, STATE.multiplier + 0.2);\n                }\n\n                if (Math.abs(car.position.z - playerGroup.position.z) < 2.5 &&\n                    Math.abs(car.position.x - playerGroup.position.x) < 1.5) {\n                    \n                    if (STATE.shieldActive) {\n                        STATE.shieldActive = false;\n                        soundFX.playCrash();\n                        scene.remove(car);\n                        trafficArray.splice(i, 1);\n                    } else {\n                        triggerGameOver();\n                        return;\n                    }\n                }\n\n                if (car.position.z > CONFIG.despawnDist) {\n                    scene.remove(car);\n                    trafficArray.splice(i, 1);\n                }\n            }\n\n            // Collectibles (Power Crystals & Shields)\n            for (let i = collectibleArray.length - 1; i >= 0; i--) {\n                const item = collectibleArray[i];\n                item.position.z += moveDist;\n                item.rotation.y += 2.5 * delta;\n                if (item.userData.ring) item.userData.ring.rotation.z += 3.0 * delta;\n                item.position.y = 1.3 + Math.sin(elapsed * 4 + i) * 0.2;\n\n                if (Math.abs(item.position.z - playerGroup.position.z) < 2.2 &&\n                    Math.abs(item.position.x - playerGroup.position.x) < 1.4) {\n                    \n                    soundFX.playPickup();\n                    if (item.userData.type === 'shield') {\n                        STATE.shieldActive = true;\n                        STATE.shieldPercent = 100;\n                    } else {\n                        STATE.cubesCollected++;\n                        STATE.multiplier = Math.min(8.0, STATE.multiplier + 0.5);\n                    }\n\n                    scene.remove(item);\n                    collectibleArray.splice(i, 1);\n                    continue;\n                }\n\n                if (item.position.z > CONFIG.despawnDist) {\n                    scene.remove(item);\n                    collectibleArray.splice(i, 1);\n                }\n            }\n\n            // Particle sparks simulation\n            for (let i = particlesArray.length - 1; i >= 0; i--) {\n                const p = particlesArray[i];\n                p.position.add(p.userData.velocity);\n                p.material.opacity -= delta * 2.2;\n                p.scale.multiplyScalar(0.94);\n                \n                if (p.material.opacity <= 0) {\n                    scene.remove(p);\n                    particlesArray.splice(i, 1);\n                }\n            }\n\n            if (Math.random() < 0.032) spawnTraffic();\n            if (Math.random() < 0.016) spawnCollectible();\n        }\n\n        function updateHUD() {\n            const speedEl = document.getElementById('hud-speed');\n            if (speedEl) speedEl.innerText = STATE.kmh;\n\n            const distEl = document.getElementById('hud-distance');\n            if (distEl) distEl.innerHTML = STATE.distance + ' <span class=\"text-xs text-orange-400 font-normal\">M</span>';\n\n            const dodgedEl = document.getElementById('hud-dodged');\n            if (dodgedEl) dodgedEl.innerText = STATE.dodgedTraffic;\n\n            const multEl = document.getElementById('hud-multiplier');\n            if (multEl) multEl.innerText = STATE.multiplier.toFixed(1) + 'x';\n            \n            const nitroBar = document.getElementById('hud-nitro-bar');\n            if (nitroBar) nitroBar.style.width = STATE.nitroLevel + '%';\n\n            const nitroPercent = document.getElementById('hud-nitro-percent');\n            if (nitroPercent) nitroPercent.innerText = Math.round(STATE.nitroLevel) + '%';\n\n            const shieldBar = document.getElementById('hud-shield-bar');\n            const shieldStatus = document.getElementById('hud-shield-status');\n            if (shieldBar && shieldStatus) {\n                if (STATE.shieldActive) {\n                    shieldBar.style.width = '100%';\n                    shieldStatus.innerText = 'ACTIVE';\n                    shieldStatus.className = 'font-orbitron text-cyan-300 font-bold animate-pulse';\n                } else {\n                    shieldBar.style.width = '0%';\n                    shieldStatus.innerText = 'OFFLINE';\n                    shieldStatus.className = 'font-orbitron text-gray-500 font-bold';\n                }\n            }\n\n            drawSpeedoGauge();\n        }\n\n        function drawSpeedoGauge() {\n            const canvas = document.getElementById('speedo-gauge');\n            if (!canvas) return;\n            const ctx = canvas.getContext('2d');\n            ctx.clearRect(0, 0, 100, 100);\n\n            const ratio = Math.min(1.0, STATE.kmh / (CONFIG.maxSpeed * CONFIG.nitroSpeedMultiplier * 170));\n            const startAngle = Math.PI * 0.75;\n            const endAngle = Math.PI * 2.25;\n\n            // Background gauge track\n            ctx.beginPath();\n            ctx.arc(50, 50, 38, startAngle, endAngle);\n            ctx.strokeStyle = 'rgba(255, 255, 255, 0.12)';\n            ctx.lineWidth = 7;\n            ctx.stroke();\n\n            // Active gauge arc\n            ctx.beginPath();\n            ctx.arc(50, 50, 38, startAngle, startAngle + (endAngle - startAngle) * ratio);\n            ctx.strokeStyle = STATE.nitroActive ? '#00f3ff' : '#00ff88';\n            ctx.lineWidth = 7;\n            ctx.shadowBlur = 10;\n            ctx.shadowColor = STATE.nitroActive ? '#00f3ff' : '#00ff88';\n            ctx.stroke();\n            ctx.shadowBlur = 0;\n        }\n\n        function applyTheme(themeKey) {\n            STATE.theme = themeKey;\n            const theme = THEMES[themeKey];\n\n            if (scene) {\n                scene.background.setHex(theme.horizon);\n                if (scene.fog) scene.fog.color.setHex(theme.fog);\n            }\n            if (gridHelper) gridHelper.material.color.setHex(theme.grid);\n\n            // Update lane lines color\n            laneLinesArray.forEach(stripe => {\n                stripe.material.color.setHex(theme.laneGlow);\n            });\n\n            document.querySelectorAll('.theme-chip').forEach(function(chip) {\n                if (chip.getAttribute('data-theme') === themeKey) {\n                    chip.classList.add('active');\n                } else {\n                    chip.classList.remove('active');\n                }\n            });\n        }\n\n        function startGame() {\n            soundFX.init();\n            STATE.active = true;\n            STATE.paused = false;\n            STATE.distance = 0;\n            STATE.dodgedTraffic = 0;\n            STATE.cubesCollected = 0;\n            STATE.multiplier = 1.0;\n            STATE.nitroLevel = 100;\n            STATE.playerX = 0;\n            STATE.targetPlayerX = 0;\n            STATE.shieldActive = false;\n\n            trafficArray.forEach(function(t) { scene.remove(t); });\n            collectibleArray.forEach(function(c) { scene.remove(c); });\n            trafficArray = [];\n            collectibleArray = [];\n            \n            particlesArray.forEach(function(p) { scene.remove(p); });\n            particlesArray = [];\n\n            const menu = document.getElementById('menu-overlay');\n            if (menu) menu.classList.add('opacity-0', 'pointer-events-none');\n            const go = document.getElementById('gameover-overlay');\n            if (go) go.classList.add('hidden');\n            const pause = document.getElementById('pause-overlay');\n            if (pause) pause.classList.add('hidden');\n        }\n\n        function triggerGameOver() {\n            soundFX.playCrash();\n            STATE.active = false;\n\n            if (STATE.distance > STATE.highScore) {\n                STATE.highScore = STATE.distance;\n                try {\n                    localStorage.setItem('neon_velocity_highscore', STATE.highScore.toString());\n                } catch (e) {}\n            }\n\n            const goDist = document.getElementById('go-distance');\n            if (goDist) goDist.innerText = STATE.distance + ' M';\n            const goSpeed = document.getElementById('go-top-speed');\n            if (goSpeed) goSpeed.innerText = STATE.topKmh + ' KM/H';\n            const goDodged = document.getElementById('go-dodged');\n            if (goDodged) goDodged.innerText = STATE.dodgedTraffic;\n            const goCubes = document.getElementById('go-cubes');\n            if (goCubes) goCubes.innerText = STATE.cubesCollected;\n            const menuScore = document.getElementById('menu-high-score');\n            if (menuScore) menuScore.innerText = STATE.highScore + ' M';\n\n            const go = document.getElementById('gameover-overlay');\n            if (go) go.classList.remove('hidden');\n        }\n\n        function togglePause() {\n            if (!STATE.active) return;\n            STATE.paused = !STATE.paused;\n            const pause = document.getElementById('pause-overlay');\n            if (pause) {\n                if (STATE.paused) pause.classList.remove('hidden');\n                else pause.classList.add('hidden');\n            }\n        }\n\n        // UI Event Bindings\n        const btnStart = document.getElementById('btn-start-game');\n        if (btnStart) btnStart.addEventListener('click', startGame);\n\n        const btnRestart = document.getElementById('btn-restart');\n        if (btnRestart) btnRestart.addEventListener('click', startGame);\n\n        const btnPause = document.getElementById('btn-pause');\n        if (btnPause) btnPause.addEventListener('click', togglePause);\n\n        const btnResume = document.getElementById('btn-resume');\n        if (btnResume) btnResume.addEventListener('click', togglePause);\n\n        const btnPauseRestart = document.getElementById('btn-pause-restart');\n        if (btnPauseRestart) {\n            btnPauseRestart.addEventListener('click', function() {\n                togglePause();\n                startGame();\n            });\n        }\n\n        const btnCam = document.getElementById('btn-cam-switch');\n        if (btnCam) btnCam.addEventListener('click', switchCameraView);\n\n        document.querySelectorAll('.theme-chip').forEach(function(chip) {\n            chip.addEventListener('click', function() {\n                const themeKey = chip.getAttribute('data-theme');\n                if (themeKey) applyTheme(themeKey);\n            });\n        });\n\n        const nitroBtn = document.getElementById('btn-nitro-boost');\n        if (nitroBtn) {\n            nitroBtn.addEventListener('touchstart', function(e) { e.preventDefault(); keys['Space'] = true; });\n            nitroBtn.addEventListener('touchend', function(e) { e.preventDefault(); keys['Space'] = false; });\n            nitroBtn.addEventListener('mousedown', function() { keys['Space'] = true; });\n            nitroBtn.addEventListener('mouseup', function() { keys['Space'] = false; });\n        }\n\n        const crtToggle = document.getElementById('toggle-crt');\n        if (crtToggle) {\n            crtToggle.addEventListener('change', function(e) {\n                if (filmPass) filmPass.enabled = e.target.checked;\n            });\n        }\n\n        const ps2Toggle = document.getElementById('toggle-ps2-res');\n        if (ps2Toggle) {\n            ps2Toggle.addEventListener('change', function(e) {\n                if (renderer) {\n                    if (e.target.checked) {\n                        renderer.setPixelRatio(0.75);\n                        renderer.domElement.classList.add('retro-pixelated');\n                    } else {\n                        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n                        renderer.domElement.classList.remove('retro-pixelated');\n                    }\n                }\n            });\n        }\n\n        const audioToggle = document.getElementById('btn-audio-toggle');\n        if (audioToggle) {\n            audioToggle.addEventListener('click', function() {\n                soundFX.enabled = !soundFX.enabled;\n                const icon = audioToggle.querySelector('i');\n                if (icon) {\n                    icon.className = soundFX.enabled ? 'fa-solid fa-volume-high text-sm' : 'fa-solid fa-volume-xmark text-sm';\n                }\n            });\n        }\n\n        function onWindowResize() {\n            if (!camera || !renderer) return;\n            camera.aspect = window.innerWidth / window.innerHeight;\n            camera.updateProjectionMatrix();\n            renderer.setSize(window.innerWidth, window.innerHeight);\n            if (composer) composer.setSize(window.innerWidth, window.innerHeight);\n        }\n\n        let lastTime = performance.now();\n        const startTime = performance.now();\n\n        function animate(currentTime) {\n            requestAnimationFrame(animate);\n\n            const delta = Math.min((currentTime - lastTime) / 1000, 0.1);\n            const elapsed = (currentTime - startTime) / 1000;\n            lastTime = currentTime;\n\n            if (STATE.active && !STATE.paused) {\n                updatePlayer(delta, elapsed);\n                updateWorld(delta, elapsed);\n                updateHUD();\n            }\n\n            if (sunMesh) sunMesh.rotation.z += 0.03 * delta;\n            if (starParticles) starParticles.rotation.y += 0.008 * delta;\n\n            if (composer) {\n                try {\n                    composer.render();\n                } catch (e) {\n                    composer = null;\n                    renderer.render(scene, camera);\n                }\n            } else if (renderer && scene && camera) {\n                renderer.render(scene, camera);\n            }\n        }\n\n        if (document.readyState === 'loading') {\n            window.addEventListener('DOMContentLoaded', function() {\n                initThree();\n                animate(performance.now());\n            });\n        } else {\n            initThree();\n            animate(performance.now());\n        }\n    </script>\n</body>\n</html>";

    // 2. VARIABEL STATE
    let editor = null;
    let isDragging = false;
    let splitRatio = 50;
    let consoleLogs = [];
    let isFullscreen = false;
    let currentFontSize = 13;
    let isWordWrap = false;

    // DOM Elements
    const leftPane = document.getElementById("left-pane");
    const rightPane = document.getElementById("right-pane");
    const splitResizer = document.getElementById("split-resizer");
    const iframe = document.getElementById("preview-iframe");
    const previewWrapper = document.getElementById("preview-frame-wrapper");
    const loadingOverlay = document.getElementById("preview-loading-overlay");
    const consoleDrawer = document.getElementById("console-drawer");
    const consoleLogsContainer = document.getElementById("console-logs-container");
    const consoleCountBadge = document.getElementById("console-count-badge");
    const consoleTotalCount = document.getElementById("console-total-count");
    const lastRunBadge = document.getElementById("last-run-badge");
    const runBtn = document.getElementById("btn-run");
    const runIcon = document.getElementById("run-icon");
    const editorLoader = document.getElementById("editor-loader");

    // 3. INSTRUMENTASI KODE (CONSOLE POSTMESSAGE BRIDGE)
    function instrumentCode(rawCode) {
        const bridgeScript = '<script>' +
        '(function() {' +
            'const sendLog = function(type, args) {' +
                'try {' +
                    'const formatted = Array.from(args).map(function(arg) {' +
                        'if (typeof arg === "object" && arg !== null) {' +
                            'try { return JSON.stringify(arg, null, 2); } catch (e) { return String(arg); }' +
                        '}' +
                        'return String(arg);' +
                    '}).join(" ");' +
                    'window.parent.postMessage({' +
                        'source: "devstudio-sandbox",' +
                        'type: type,' +
                        'message: formatted,' +
                        'time: new Date().toLocaleTimeString()' +
                    '}, "*");' +
                '} catch (e) {}' +
            '};' +
            'const origLog = console.log;' +
            'const origWarn = console.warn;' +
            'const origError = console.error;' +
            'const origInfo = console.info;' +

            'console.log = function() { sendLog("log", arguments); origLog.apply(console, arguments); };' +
            'console.warn = function() { sendLog("warn", arguments); origWarn.apply(console, arguments); };' +
            'console.error = function() { sendLog("error", arguments); origError.apply(console, arguments); };' +
            'console.info = function() { sendLog("info", arguments); origInfo.apply(console, arguments); };' +

            'window.onerror = function(msg, url, line, col, err) {' +
                'sendLog("error", ["[Runtime Error] " + msg + " (" + (url ? url.split("/").pop() : "inline") + ":" + line + ":" + col + ")"]);' +
                'return false;' +
            '};' +
        '})();' +
        '<\/script>';

        if (rawCode.includes('<head>')) {
            return rawCode.replace('<head>', '<head>' + bridgeScript);
        }
        return bridgeScript + rawCode;
    }

    // 4. JALANKAN KODE KE PRATINJAU IFRAME
    function runCode() {
        if (!iframe) return;
        const code = editor ? editor.getValue() : STARTER_CODE;

        if (runIcon) runIcon.classList.add("fa-spin");
        if (loadingOverlay) loadingOverlay.classList.remove("hidden");

        addConsoleLog("info", "Mengeksekusi berkas [modul-08.html] via Sandbox...");

        iframe.srcdoc = instrumentCode(code);

        const nowTime = new Date().toLocaleTimeString();
        if (lastRunBadge) lastRunBadge.textContent = "(" + nowTime + ")";

        setTimeout(function() {
            if (runIcon) runIcon.classList.remove("fa-spin");
            if (loadingOverlay) loadingOverlay.classList.add("hidden");
        }, 450);
    }

    // 5. MANAJEMEN LOG KONSOL
    function addConsoleLog(type, message) {
        const time = new Date().toLocaleTimeString();
        consoleLogs.push({ type: type, message: message, time: time });
        if (consoleLogs.length > 100) consoleLogs.shift();
        renderConsoleLogs();
    }

    function renderConsoleLogs() {
        if (!consoleLogsContainer) return;
        if (consoleCountBadge) consoleCountBadge.textContent = consoleLogs.length;
        if (consoleTotalCount) consoleTotalCount.textContent = "(" + consoleLogs.length + " pesan)";

        if (consoleLogs.length === 0) {
            consoleLogsContainer.innerHTML = '<div class="text-slate-600 italic py-3 text-center">Konsol kosong. Pesan console.log dan error dalam iframe akan muncul di sini.</div>';
            return;
        }

        consoleLogsContainer.innerHTML = consoleLogs.map(function(item) {
            let badgeClass = "text-slate-300";
            let icon = "";
            if (item.type === "error") {
                badgeClass = "bg-red-950/40 text-red-300 border-l-2 border-red-500";
                icon = '<i class="fa-solid fa-triangle-exclamation text-red-400"></i>';
            } else if (item.type === "warn") {
                badgeClass = "bg-amber-950/40 text-amber-300 border-l-2 border-amber-500";
                icon = '<i class="fa-solid fa-circle-exclamation text-amber-400"></i>';
            } else if (item.type === "info") {
                badgeClass = "bg-cyan-950/30 text-cyan-300 border-l-2 border-cyan-500";
                icon = '<i class="fa-solid fa-circle-info text-cyan-400"></i>';
            }
            return '<div class="console-log-item flex items-start gap-2 py-1 px-2 rounded ' + badgeClass + '">' +
                '<span class="text-[10px] text-slate-500 shrink-0 font-mono">' + item.time + '</span>' +
                (icon ? '<span class="shrink-0 text-xs">' + icon + '</span>' : '') +
                '<pre class="whitespace-pre-wrap break-all flex-1 font-mono text-[11px]">' + escapeHtml(item.message) + '</pre>' +
            '</div>';
        }).join("");

        consoleLogsContainer.scrollTop = consoleLogsContainer.scrollHeight;
    }

    function escapeHtml(str) {
        return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    }

    // Tangkap pesan dari Sandbox iframe via postMessage
    window.addEventListener("message", function(event) {
        if (event.data && event.data.source === "devstudio-sandbox") {
            addConsoleLog(event.data.type || "log", event.data.message || "");
        }
    });

    // 6. RESIZING DUAL-PANE (DRAGGABLE SPLITTER)
    function setSplitWidth(percent) {
        splitRatio = Math.max(20, Math.min(80, percent));
        if (leftPane) leftPane.style.width = splitRatio + "%";
        if (editor) editor.layout();
    }

    if (splitResizer) {
        splitResizer.addEventListener("mousedown", function(e) {
            e.preventDefault();
            isDragging = true;
            splitResizer.classList.add("dragging");
            document.body.style.cursor = "col-resize";
            document.body.style.userSelect = "none";
        });

        window.addEventListener("mousemove", function(e) {
            if (!isDragging) return;
            const containerWidth = window.innerWidth;
            const newRatio = (e.clientX / containerWidth) * 100;
            setSplitWidth(newRatio);
        });

        window.addEventListener("mouseup", function() {
            if (isDragging) {
                isDragging = false;
                splitResizer.classList.remove("dragging");
                document.body.style.cursor = "";
                document.body.style.userSelect = "";
            }
        });

        // Touch support for mobile / tablets
        splitResizer.addEventListener("touchstart", function(e) {
            isDragging = true;
            splitResizer.classList.add("dragging");
        });

        window.addEventListener("touchmove", function(e) {
            if (!isDragging || !e.touches[0]) return;
            const containerWidth = window.innerWidth;
            const newRatio = (e.touches[0].clientX / containerWidth) * 100;
            setSplitWidth(newRatio);
        });

        window.addEventListener("touchend", function() {
            if (isDragging) {
                isDragging = false;
                splitResizer.classList.remove("dragging");
            }
        });
    }

    // Tombol Preset Rasio
    const btnL30 = document.getElementById("btn-layout-30");
    const btnL50 = document.getElementById("btn-layout-50");
    const btnL70 = document.getElementById("btn-layout-70");

    function updatePresetHighlight(activeBtn) {
        [btnL30, btnL50, btnL70].forEach(function(b) {
            if (b) {
                b.classList.remove("bg-cyan-900/60", "text-cyan-300");
                b.classList.add("text-slate-400");
            }
        });
        if (activeBtn) {
            activeBtn.classList.remove("text-slate-400");
            activeBtn.classList.add("bg-cyan-900/60", "text-cyan-300");
        }
    }

    if (btnL30) btnL30.addEventListener("click", function() { setSplitWidth(30); updatePresetHighlight(btnL30); });
    if (btnL50) btnL50.addEventListener("click", function() { setSplitWidth(50); updatePresetHighlight(btnL50); });
    if (btnL70) btnL70.addEventListener("click", function() { setSplitWidth(70); updatePresetHighlight(btnL70); });

    // 7. INISIALISASI MONACO EDITOR
    if (typeof require !== "undefined") {
        require.config({
            paths: { vs: "https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.45.0/min/vs" }
        });

        require(["vs/editor/editor.main"], function() {
            const container = document.getElementById("editor-container");
            if (!container) return;

            editor = monaco.editor.create(container, {
                value: STARTER_CODE,
                language: "html",
                theme: "vs-dark",
                automaticLayout: true,
                fontSize: currentFontSize,
                lineNumbers: "on",
                minimap: { enabled: false },
                scrollBeyondLastLine: false,
                tabSize: 2,
                wordWrap: "off",
                padding: { top: 12, bottom: 12 }
            });

            if (editorLoader) editorLoader.classList.add("hidden");

            // Jalankan kode otomatis pertama kali agar game langsung tampil di pratinjau kanan
            runCode();
        });
    }

    // 8. EVENT LISTENER HEADER & TOOLBAR
    if (runBtn) runBtn.addEventListener("click", runCode);

    // Pintasan Keyboard Ctrl+Enter / Cmd+Enter untuk Jalankan
    window.addEventListener("keydown", function(e) {
        if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
            e.preventDefault();
            runCode();
        }
    });

    // Reset Code
    const resetBtn = document.getElementById("btn-reset-code");
    if (resetBtn) {
        resetBtn.addEventListener("click", function() {
            if (confirm("Kembalikan kode editor ke templat awal game Neon Velocity? Perubahan Anda akan direset.")) {
                if (editor) editor.setValue(STARTER_CODE);
                runCode();
                addConsoleLog("info", "Kode berhasil dikembalikan ke templat awal.");
            }
        });
    }

    // Toggle Word Wrap
    const wrapBtn = document.getElementById("btn-toggle-wrap");
    if (wrapBtn) {
        wrapBtn.addEventListener("click", function() {
            isWordWrap = !isWordWrap;
            if (editor) {
                editor.updateOptions({ wordWrap: isWordWrap ? "on" : "off" });
            }
            wrapBtn.classList.toggle("active", isWordWrap);
        });
    }

    // Font Size (+ / -)
    const fontIncBtn = document.getElementById("btn-font-inc");
    const fontDecBtn = document.getElementById("btn-font-dec");
    const fontLabel = document.getElementById("font-size-label");

    if (fontIncBtn) {
        fontIncBtn.addEventListener("click", function() {
            currentFontSize = Math.min(24, currentFontSize + 1);
            if (editor) editor.updateOptions({ fontSize: currentFontSize });
            if (fontLabel) fontLabel.textContent = currentFontSize + "px";
        });
    }
    if (fontDecBtn) {
        fontDecBtn.addEventListener("click", function() {
            currentFontSize = Math.max(10, currentFontSize - 1);
            if (editor) editor.updateOptions({ fontSize: currentFontSize });
            if (fontLabel) fontLabel.textContent = currentFontSize + "px";
        });
    }

    // Salin Kode
    const copyBtn = document.getElementById("btn-copy-code");
    const copyIcon = document.getElementById("copy-icon");
    const copyText = document.getElementById("copy-text");

    if (copyBtn) {
        copyBtn.addEventListener("click", function() {
            const textToCopy = editor ? editor.getValue() : STARTER_CODE;
            navigator.clipboard.writeText(textToCopy).then(function() {
                if (copyIcon) copyIcon.className = "fa-solid fa-check text-emerald-400 text-xs";
                if (copyText) copyText.textContent = "Tersalin!";
                setTimeout(function() {
                    if (copyIcon) copyIcon.className = "fa-solid fa-copy text-slate-400 text-xs";
                    if (copyText) copyText.textContent = "Salin";
                }, 2000);
            });
        });
    }

    // Unduh HTML Tunggal
    const downloadBtn = document.getElementById("btn-download-html");
    if (downloadBtn) {
        downloadBtn.addEventListener("click", function() {
            const textToDownload = editor ? editor.getValue() : STARTER_CODE;
            const blob = new Blob([textToDownload], { type: "text/html;charset=utf-8" });
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = "modul-08_project.html";
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        });
    }

    // Frame Devices (Desktop, Tablet, Mobile)
    const btnDevDesk = document.getElementById("btn-device-desktop");
    const btnDevTab = document.getElementById("btn-device-tablet");
    const btnDevMob = document.getElementById("btn-device-mobile");

    function setDeviceMode(mode) {
        if (!previewWrapper) return;
        previewWrapper.classList.remove("preview-viewport-desktop", "preview-viewport-tablet", "preview-viewport-mobile");
        
        [btnDevDesk, btnDevTab, btnDevMob].forEach(function(b) {
            if (b) {
                b.classList.remove("text-cyan-400", "bg-cyan-950/60");
                b.classList.add("text-slate-400");
            }
        });

        if (mode === "tablet") {
            previewWrapper.classList.add("preview-viewport-tablet");
            if (btnDevTab) {
                btnDevTab.classList.remove("text-slate-400");
                btnDevTab.classList.add("text-cyan-400", "bg-cyan-950/60");
            }
        } else if (mode === "mobile") {
            previewWrapper.classList.add("preview-viewport-mobile");
            if (btnDevMob) {
                btnDevMob.classList.remove("text-slate-400");
                btnDevMob.classList.add("text-cyan-400", "bg-cyan-950/60");
            }
        } else {
            previewWrapper.classList.add("preview-viewport-desktop");
            if (btnDevDesk) {
                btnDevDesk.classList.remove("text-slate-400");
                btnDevDesk.classList.add("text-cyan-400", "bg-cyan-950/60");
            }
        }
    }

    if (btnDevDesk) btnDevDesk.addEventListener("click", function() { setDeviceMode("desktop"); });
    if (btnDevTab) btnDevTab.addEventListener("click", function() { setDeviceMode("tablet"); });
    if (btnDevMob) btnDevMob.addEventListener("click", function() { setDeviceMode("mobile"); });

    // Reload Preview
    const reloadBtn = document.getElementById("btn-reload-preview");
    if (reloadBtn) reloadBtn.addEventListener("click", runCode);

    // Toggle Console Drawer
    const toggleConsoleBtn = document.getElementById("btn-toggle-console");
    const closeConsoleBtn = document.getElementById("btn-close-console");
    const clearConsoleBtn = document.getElementById("btn-clear-console");

    function toggleConsole() {
        if (!consoleDrawer) return;
        consoleDrawer.classList.toggle("hidden");
    }

    if (toggleConsoleBtn) toggleConsoleBtn.addEventListener("click", toggleConsole);
    if (closeConsoleBtn) closeConsoleBtn.addEventListener("click", function() {
        if (consoleDrawer) consoleDrawer.classList.add("hidden");
    });
    if (clearConsoleBtn) clearConsoleBtn.addEventListener("click", function() {
        consoleLogs = [];
        renderConsoleLogs();
    });

    // Fullscreen Toggle
    const fullscreenBtn = document.getElementById("btn-fullscreen");
    const fullscreenIcon = document.getElementById("fullscreen-icon");

    if (fullscreenBtn) {
        fullscreenBtn.addEventListener("click", function() {
            if (!document.fullscreenElement) {
                if (previewWrapper.requestFullscreen) {
                    previewWrapper.requestFullscreen();
                }
            } else {
                if (document.exitFullscreen) {
                    document.exitFullscreen();
                }
            }
        });
    }

    document.addEventListener("fullscreenchange", function() {
        isFullscreen = !!document.fullscreenElement;
        if (fullscreenIcon) {
            fullscreenIcon.className = isFullscreen ? "fa-solid fa-compress text-[11px]" : "fa-solid fa-expand text-[11px]";
        }
    });

    // Help Modal
    const helpBtn = document.getElementById("btn-help-modal");
    const helpModal = document.getElementById("help-modal");
    const closeHelpBtn = document.getElementById("btn-close-help");
    const dismissHelpBtn = document.getElementById("btn-dismiss-help");

    if (helpBtn && helpModal) {
        helpBtn.addEventListener("click", function() { helpModal.classList.remove("hidden"); });
    }
    if (closeHelpBtn && helpModal) {
        closeHelpBtn.addEventListener("click", function() { helpModal.classList.add("hidden"); });
    }
    if (dismissHelpBtn && helpModal) {
        dismissHelpBtn.addEventListener("click", function() { helpModal.classList.add("hidden"); });
    }

    // Window Resize Handler
    window.addEventListener("resize", function() {
        if (editor) editor.layout();
    });

})();
